window.TL_GQ = [{"cat":"禮貌問候","kind":"tf","q":"早上遇到老師，主動說「老師早」是有禮貌的表現。","a":"是","w":["否"],"ex":"主動問候，讓人感覺被尊重。","id":"g001"},{"cat":"禮貌問候","kind":"tf","q":"只有認識的人才需要問候，遇到不認識的長輩可以假裝沒看到。","a":"否","w":["是"],"ex":"有禮貌的人，對長輩都可以微笑點頭問好。","id":"g002"},{"cat":"禮貌問候","kind":"tf","q":"跟別人說話時，看著對方的眼睛是一種尊重。","a":"是","w":["否"],"ex":"眼神交流表示你很專心。","id":"g003"},{"cat":"禮貌問候","kind":"tf","q":"別人跟你說「早安」，你可以不用回應。","a":"否","w":["是"],"ex":"被問候時，回一聲問好才有禮貌。","id":"g004"},{"cat":"禮貌問候","kind":"tf","q":"進別人的辦公室或教室前，要先敲門或打招呼。","a":"是","w":["否"],"ex":"先敲門，是尊重對方的空間。","id":"g005"},{"cat":"禮貌問候","kind":"tf","q":"跟長輩說話時，可以直接叫他的綽號，不用稱呼。","a":"否","w":["是"],"ex":"要用適當的稱呼，例如老師、阿姨、爺爺。","id":"g006"},{"cat":"禮貌問候","kind":"tf","q":"拜託別人幫忙時，說「請」會讓對方更願意幫你。","a":"是","w":["否"],"ex":"「請」讓人感覺被尊重。","id":"g007"},{"cat":"禮貌問候","kind":"tf","q":"別人在說話時，可以隨時插嘴，只要你說的比較重要。","a":"否","w":["是"],"ex":"等對方說完再說，才是尊重。","id":"g008"},{"cat":"禮貌問候","kind":"tf","q":"吃飯前跟同桌的人說「我開動了」是一種禮貌。","a":"是","w":["否"],"ex":"表達感謝，也是用餐禮儀。","id":"g009"},{"cat":"禮貌問候","kind":"tf","q":"在走廊遇到同學，只要點頭微笑就是一種問候。","a":"是","w":["否"],"ex":"問候不一定要大聲，微笑點頭也可以。","id":"g010"},{"cat":"禮貌問候","kind":"tf","q":"借用別人的東西，不用問，直接拿就好。","a":"否","w":["是"],"ex":"借東西要先問過，得到同意再拿。","id":"g011"},{"cat":"禮貌問候","kind":"tf","q":"搭電梯時，先讓裡面的人出來，再進去，是有禮貌的做法。","a":"是","w":["否"],"ex":"先下後上，大家都方便。","id":"g012"},{"cat":"禮貌問候","kind":"tf","q":"別人遞東西給你時，用雙手接是比較有禮貌的方式。","a":"是","w":["否"],"ex":"雙手接，表示重視與尊敬。","id":"g013"},{"cat":"禮貌問候","kind":"tf","q":"跟別人約好時間，遲到了也不用說抱歉。","a":"否","w":["是"],"ex":"遲到要誠懇道歉，也是尊重別人的時間。","id":"g014"},{"cat":"禮貌問候","kind":"tf","q":"在圖書館裡可以大聲聊天，因為大家都是同學。","a":"否","w":["是"],"ex":"公共空間要輕聲細語，不打擾別人。","id":"g015"},{"cat":"禮貌問候","kind":"tf","q":"別人問你話，只用點頭或搖頭，不出聲，也算很有禮貌。","a":"否","w":["是"],"ex":"能回答的時候，用清楚的話回應比較好。","id":"g016"},{"cat":"禮貌問候","kind":"tf","q":"遇到打掃的工友伯伯，主動說聲「辛苦了」是很棒的行為。","a":"是","w":["否"],"ex":"對每一位為學校付出的人都要尊重。","id":"g017"},{"cat":"禮貌問候","kind":"tf","q":"只要老師沒看到，就可以不用說「請」和「謝謝」。","a":"否","w":["是"],"ex":"禮貌是習慣，不是做給別人看的。","id":"g018"},{"cat":"禮貌問候","kind":"tf","q":"通過窄窄的走廊時，遇到對面的人，可以側身讓他先過。","a":"是","w":["否"],"ex":"禮讓是一種體貼。","id":"g019"},{"cat":"禮貌問候","kind":"tf","q":"長輩給你東西，你覺得不需要，就可以直接說「我不要」。","a":"否","w":["是"],"ex":"可以禮貌地說「謝謝，我不需要」。","id":"g020"},{"cat":"禮貌問候","kind":"tf","q":"說話時，用溫和的語氣比大聲吼叫更容易被人接受。","a":"是","w":["否"],"ex":"好語氣讓溝通更順利。","id":"g021"},{"cat":"禮貌問候","kind":"tf","q":"別人有困難時，你伸出援手，也是有禮貌的一種。","a":"是","w":["否"],"ex":"禮貌也包含關心與體貼。","id":"g022"},{"cat":"禮貌問候","kind":"tf","q":"分組討論時，只有自己一個人一直講，是很有禮貌的。","a":"否","w":["是"],"ex":"輪流發言，尊重大家的想法。","id":"g023"},{"cat":"禮貌問候","kind":"tf","q":"接電話時，先說「您好」再說明身分是比較有禮貌的。","a":"是","w":["否"],"ex":"有禮貌的開場，讓對方安心。","id":"g024"},{"cat":"禮貌問候","kind":"tf","q":"看到同學的東西掉了，裝作沒看到就好。","a":"否","w":["是"],"ex":"撿起來還給他，是友善的表現。","id":"g025"},{"cat":"禮貌問候","kind":"tf","q":"在別人家作客，可以不問主人，直接翻東西。","a":"否","w":["是"],"ex":"作客要守規矩，先詢問再使用。","id":"g026"},{"cat":"禮貌問候","kind":"tf","q":"遇到校長，點頭微笑說「校長好」是有禮貌的問候。","a":"是","w":["否"],"ex":"問候是尊重的開始。","id":"g027"},{"cat":"禮貌問候","kind":"tf","q":"別人在忙的時候，我們可以先說「請問您現在方便嗎」。","a":"是","w":["否"],"ex":"先詢問，是體貼的做法。","id":"g028"},{"cat":"禮貌問候","kind":"tf","q":"對同學說「謝謝」只是客套，不需要真的說出口。","a":"否","w":["是"],"ex":"說出口，對方才知道你的感謝。","id":"g029"},{"cat":"禮貌問候","kind":"tf","q":"回答問題時，說「我不知道」，語氣不耐煩也沒關係。","a":"否","w":["是"],"ex":"即使不知道，也可以溫和地回答。","id":"g030"},{"cat":"禮貌問候","kind":"mc","q":"早上走進教室，看到老師，最適合說什麼？","a":"老師早安！","w":["嗯。","你怎麼那麼早？"],"ex":"主動問好，讓人感覺愉快。","id":"g031"},{"cat":"禮貌問候","kind":"mc","q":"別人幫了你的忙，你應該怎麼說？","a":"謝謝你幫我！","w":["這是你應該做的。","不用你多事。"],"ex":"感謝的話要說出口。","id":"g032"},{"cat":"禮貌問候","kind":"mc","q":"想借同學的鉛筆，下列哪個說法最有禮貌？","a":"請問我可以借你的鉛筆嗎？","w":["鉛筆給我！","我要用你的鉛筆。"],"ex":"問一問，再得到同意。","id":"g033"},{"cat":"禮貌問候","kind":"mc","q":"不小心撞到別人，第一時間應該說什麼？","a":"對不起，你還好嗎？","w":["你怎麼擋在那裡？","哎呀，沒事啦。"],"ex":"道歉加關心，最有誠意。","id":"g034"},{"cat":"禮貌問候","kind":"mc","q":"遇到不認識的鄰居長輩，最適合怎麼做？","a":"微笑點頭，問聲好","w":["低頭快步走過","裝作沒看到"],"ex":"友善的問候，讓社區更溫暖。","id":"g035"},{"cat":"禮貌問候","kind":"mc","q":"別人正在說話，你有想說的話，應該怎麼做？","a":"等對方說完再舉手或開口","w":["直接大聲打斷","在旁邊一直插話"],"ex":"等待是尊重的表現。","id":"g036"},{"cat":"禮貌問候","kind":"mc","q":"在公車上看到老人家站著，你可以怎麼做？","a":"主動讓座給他","w":["假裝在睡覺","低頭玩手機"],"ex":"讓座是一種溫暖的禮貌。","id":"g037"},{"cat":"禮貌問候","kind":"mc","q":"要請同學幫忙遞東西，最適合的說法是？","a":"可以請你幫我遞一下嗎？謝謝！","w":["喂，拿過來！","你快點給我。"],"ex":"請與謝謝，是最棒的搭配。","id":"g038"},{"cat":"禮貌問候","kind":"mc","q":"別人跟你道謝，你可以怎麼回應？","a":"不客氣！","w":["嗯。","你本來就該謝我。"],"ex":"禮貌的回應讓對話更溫暖。","id":"g039"},{"cat":"禮貌問候","kind":"mc","q":"到同學家玩，離開時要說什麼？","a":"謝謝招待，我先回去了","w":["我要走了","沒什麼好玩的"],"ex":"感謝主人的招待，是基本禮貌。","id":"g040"},{"cat":"禮貌問候","kind":"mc","q":"在電影院或表演場合，手機應該怎麼處理？","a":"調成靜音或關機","w":["大聲播放音樂","一直講電話"],"ex":"不打擾別人，是公共禮儀。","id":"g041"},{"cat":"禮貌問候","kind":"mc","q":"同學考試考得很好，你可以怎麼說？","a":"恭喜你！你很棒！","w":["只是運氣好啦","有什麼了不起"],"ex":"真心的祝賀，讓朋友開心。","id":"g042"},{"cat":"禮貌問候","kind":"mc","q":"有人跟你說「對不起」，你可以怎麼回答？","a":"沒關係，謝謝你告訴我","w":["哼，不原諒你","你要賠我"],"ex":"接受道歉，讓關係更好。","id":"g043"},{"cat":"禮貌問候","kind":"mc","q":"看到老師提著重物，你可以怎麼做？","a":"問老師需不需要幫忙","w":["假裝沒看到","在旁邊看著就好"],"ex":"主動關心，展現同理與禮貌。","id":"g044"},{"cat":"禮貌問候","kind":"mc","q":"和長輩說話時，下列哪一種稱呼最合適？","a":"阿姨好、爺爺好","w":["喂、欸","你、妳"],"ex":"有禮貌的稱呼，是尊重的第一步。","id":"g045"},{"cat":"禮貌問候","kind":"mc","q":"下課時，同學在教室外面等你，你想先去洗手間，應該怎麼說？","a":"等我一下，我去洗手間馬上回來","w":["你先走啦","我先去，不管你了"],"ex":"說明原因，對方不會誤會。","id":"g046"},{"cat":"禮貌問候","kind":"mc","q":"進入有人在睡覺的午休教室，應該怎麼做？","a":"輕輕開門、放輕腳步","w":["大聲打招呼","用力關門"],"ex":"安靜，是午休時的體貼。","id":"g047"},{"cat":"禮貌問候","kind":"mc","q":"校外教學搭遊覽車時，下列哪一種做法有禮貌？","a":"輕聲聊天、整理垃圾","w":["大聲唱歌不理人","把垃圾丟在座位下"],"ex":"愛護公共空間，也是禮貌。","id":"g048"},{"cat":"禮貌問候","kind":"mc","q":"在餐廳吃飯，服務人員幫你上菜，你可以怎麼做？","a":"說聲謝謝","w":["完全不理人","大聲催促他"],"ex":"對服務的人說謝謝，就是尊重。","id":"g049"},{"cat":"禮貌問候","kind":"mc","q":"有朋友邀請你參加生日派對，但你那天有事，該怎麼回答？","a":"謝謝邀請，可是那天我有事，真的很抱歉","w":["我才不要去","不理他，假裝沒聽到"],"ex":"誠懇回絕，不傷感情。","id":"g050"},{"cat":"禮貌問候","kind":"mc","q":"與人談話時，下列哪一種態度最有禮貌？","a":"專心看著對方、適時回應","w":["一直看手機","東張西望"],"ex":"專注是最好的尊重。","id":"g051"},{"cat":"禮貌問候","kind":"mc","q":"在升旗典禮時，下列哪一種表現是有禮貌的？","a":"站好、安靜、面向國旗","w":["聊天、嬉鬧","蹲在地上玩"],"ex":"莊嚴的場合，要守規矩。","id":"g052"},{"cat":"禮貌問候","kind":"mc","q":"不小心打破了學校的東西，應該怎麼做？","a":"主動告訴老師並道歉","w":["偷偷藏起來","怪罪給別人"],"ex":"誠實面對，大家才會原諒你。","id":"g053"},{"cat":"禮貌問候","kind":"mc","q":"有人邀請你一起玩，你不想玩，可以怎麼說？","a":"謝謝你，我今天想自己休息一下","w":["不要，很無聊","走開啦"],"ex":"拒絕也可以很溫柔。","id":"g054"},{"cat":"禮貌問候","kind":"mc","q":"晚上經過鄰居家，下列哪一種做法比較有禮貌？","a":"放輕腳步、小聲說話","w":["大聲說笑奔跑","用力拍打大門"],"ex":"不吵到鄰居，是社區禮儀。","id":"g055"},{"cat":"禮貌問候","kind":"mc","q":"同學說了一個你已經聽過的笑話，你可以怎麼做？","a":"笑一笑，讓他說完","w":["說「我聽過了，好無聊」","直接走開"],"ex":"體貼別人的心意，比炫耀更重要。","id":"g056"},{"cat":"禮貌問候","kind":"mc","q":"吃飯時，嘴巴裡有食物，這時有人叫你，下列哪個做法比較好？","a":"先把食物吃完或吞下，再回答","w":["含著食物大聲回答","吐出來再回答"],"ex":"有禮貌的人，會顧及餐桌禮儀。","id":"g057"},{"cat":"禮貌問候","kind":"mc","q":"有客人來學校參觀，遇到時你可以怎麼做？","a":"微笑點頭、說「歡迎來我們學校」","w":["盯著他們一直看","躲起來偷笑"],"ex":"當小主人，也要有禮貌。","id":"g058"},{"cat":"禮貌問候","kind":"mc","q":"在別人看書或寫作業時，需要經過旁邊，你可以怎麼做？","a":"輕聲說「不好意思」再經過","w":["直接用力擠過去","大聲叫他讓開"],"ex":"輕聲打招呼，是尊重專心的人。","id":"g059"},{"cat":"禮貌問候","kind":"mc","q":"同學的鞋帶鬆了，你發現時，你可以怎麼說？","a":"你的鞋帶鬆了，小心會跌倒喔","w":["你很笨，鞋帶都不會綁","不用管他"],"ex":"溫柔提醒，是關心也是禮貌。","id":"g060"},{"cat":"禮貌問候","kind":"mc","q":"整理完房間，爸媽誇獎你，你可以怎麼回答？","a":"謝謝爸爸媽媽，我會繼續努力","w":["這沒什麼啦","你們才會整理吧"],"ex":"用感謝回應稱讚，很有禮貌。","id":"g061"},{"cat":"禮貌問候","kind":"mc","q":"在別人面前打哈欠或打噴嚏，下列哪個做法比較有禮貌？","a":"用手或衣袖遮住口鼻","w":["對著人直接噴","大聲張嘴"],"ex":"遮住口鼻，是衛生也是禮貌。","id":"g062"},{"cat":"禮貌問候","kind":"mc","q":"收到別人送的禮物，不管喜不喜歡，應該怎麼做？","a":"微笑說「謝謝你，我很開心」","w":["說「我不喜歡這個」","直接丟在一旁"],"ex":"心意比禮物更重要。","id":"g063"},{"cat":"禮貌問候","kind":"mc","q":"上課遲到進教室，最適當的做法是？","a":"輕聲說報告，並向老師說明原因","w":["直接走進去坐下","大聲說「我來了」"],"ex":"說明理由，也是對老師的尊重。","id":"g064"},{"cat":"禮貌問候","kind":"mc","q":"和朋友借了書，還書時要怎麼做？","a":"說謝謝，並保持書本完整","w":["隨便丟在桌上","不還，假裝忘記"],"ex":"有借有還，再借不難。","id":"g065"},{"cat":"禮貌問候","kind":"mc","q":"在公共場所遇到朋友，想打招呼，下列哪一種方式比較合適？","a":"走近一點，輕聲打招呼","w":["隔很遠大聲喊他的名字","從後面用力拍他"],"ex":"在公共場所，輕聲打招呼比較不打擾別人。","id":"g066"},{"cat":"禮貌問候","kind":"mc","q":"在餐廳或百貨公司，小朋友應該怎麼做？","a":"坐好、輕聲說話","w":["在店裡奔跑尖叫","爬上桌椅玩耍"],"ex":"公共場所，守規矩才安全。","id":"g067"},{"cat":"禮貌問候","kind":"mc","q":"師長講話時，你想問問題，應該怎麼做？","a":"先舉手，得到允許再發言","w":["隨時大聲喊","直接走到老師面前打斷"],"ex":"舉手發言，是課堂的基本禮貌。","id":"g068"},{"cat":"禮貌問候","kind":"mc","q":"在別人家作客，主人端茶出來，你可以怎麼說？","a":"謝謝您，不好意思麻煩了","w":["太燙了啦","我不喝這個"],"ex":"道謝也代表你很懂禮貌。","id":"g069"},{"cat":"禮貌問候","kind":"mc","q":"朋友買了新鉛筆盒，你覺得很漂亮，可以怎麼說？","a":"你的鉛筆盒好漂亮喔","w":["這很普通耶","我家有更貴的"],"ex":"真心的讚美，讓人開心。","id":"g070"},{"cat":"禮貌問候","kind":"mc","q":"在校門口遇到值勤的志工媽媽，你可以怎麼做？","a":"微笑說「謝謝媽媽，早安」","w":["低頭走過去","大聲嘲笑"],"ex":"感謝志工的付出，是最棒的禮貌。","id":"g071"},{"cat":"禮貌問候","kind":"mc","q":"需要別人讓路時，下列哪一句最合適？","a":"不好意思，請借過一下","w":["讓開啦","你擋到我了"],"ex":"客氣說話，大家都開心。","id":"g072"},{"cat":"禮貌問候","kind":"mc","q":"老師發考卷時遞給你，你可以怎麼做？","a":"雙手接、說謝謝","w":["單手搶過來","不看老師直接拿走"],"ex":"有禮貌的接收，展現尊重。","id":"g073"},{"cat":"禮貌問候","kind":"mc","q":"跟朋友吵架後，想要和好，可以怎麼開口？","a":"對不起，我們可以和好嗎？","w":["你先道歉我才要理你","我才沒有錯"],"ex":"主動示好，需要勇氣也是禮貌。","id":"g074"},{"cat":"禮貌問候","kind":"mc","q":"在別人家，想使用廁所，應該怎麼說？","a":"請問可以借用一下廁所嗎？","w":["廁所在哪？我要上","我進去了"],"ex":"詢問主人，是客人的禮貌。","id":"g075"},{"cat":"禮貌問候","kind":"mc","q":"表演結束時，看台下觀眾應該怎麼做？","a":"熱情鼓掌，表達欣賞","w":["大聲噓聲","直接離開座位"],"ex":"鼓掌是給表演者最好的回應。","id":"g076"},{"cat":"禮貌問候","kind":"mc","q":"搭捷運或公車，上車前應該先做什麼？","a":"讓車上的人先下車","w":["直接往前擠","大聲喊「讓開」"],"ex":"先下後上，大家都方便。","id":"g077"},{"cat":"禮貌問候","kind":"mc","q":"在餐廳想要加點飲料，下列哪一種做法比較有禮貌？","a":"舉手示意，輕聲向服務生說「麻煩你」","w":["大聲吼叫「喂！」","用手指指向服務生"],"ex":"有禮貌的請求，更容易得到好服務。","id":"g078"},{"cat":"禮貌問候","kind":"mc","q":"有人幫你拍照，拍完後你可以怎麼說？","a":"謝謝你幫我拍照！","w":["你拍得好爛","別拍了啦"],"ex":"禮貌地道謝，讓人心情好。","id":"g079"},{"cat":"禮貌問候","kind":"mc","q":"看到朋友心情不好，一開始應該怎麼問比較有禮貌？","a":"你還好嗎？想聊聊嗎？","w":["你怎麼了？快說！","你很煩耶"],"ex":"溫和地關心，不勉強對方說。","id":"g080"},{"cat":"禮貌問候","kind":"mc","q":"在教室裡要借用同學桌上的橡皮擦，最適合怎麼做？","a":"先問「可以借我用一下嗎」","w":["直接拿走","丟給他一張紙條說我拿走了"],"ex":"尊重物品的主人，先問再借。","id":"g081"},{"cat":"禮貌問候","kind":"mc","q":"老師提醒你上課說話要小聲，你應該怎麼回應？","a":"說「好的老師，我知道了」","w":["不理老師","頂嘴說「是他先講的」"],"ex":"接受提醒，是尊重的態度。","id":"g082"},{"cat":"禮貌問候","kind":"mc","q":"新同學轉來，你可以怎麼做？","a":"微笑介紹自己，邀請他一起玩","w":["假裝沒看到","在背後講他壞話"],"ex":"友善的歡迎，讓新同學安心。","id":"g083"},{"cat":"禮貌問候","kind":"mc","q":"校外教學要排隊進場時，應該怎麼做？","a":"依序排隊，不插隊","w":["擠到最前面","大聲喧嘩不排隊"],"ex":"守秩序，是對大家的尊重。","id":"g084"},{"cat":"禮貌問候","kind":"mc","q":"別人邀請你吃東西，你已經吃飽了，可以怎麼說？","a":"謝謝你，我吃飽了，下次再吃","w":["不要，我不吃那個","看起來很難吃"],"ex":"婉拒時說謝謝，讓人感覺舒服。","id":"g085"},{"cat":"禮貌問候","kind":"mc","q":"在電話裡聽不清楚對方說什麼，可以怎麼做？","a":"請問可以再說一次嗎？","w":["大叫「聽不到啦」","直接掛掉"],"ex":"禮貌地請對方重複，溝通才順暢。","id":"g086"},{"cat":"感謝道歉","kind":"tf","q":"同學借你橡皮擦，說一聲「謝謝」，可以讓對方覺得被重視。","a":"是","w":["否"],"ex":"小小的謝謝，大大的溫暖。","id":"g087"},{"cat":"感謝道歉","kind":"tf","q":"我不是故意的，所以不用道歉。","a":"否","w":["是"],"ex":"就算不是故意，造成別人困擾也可以說對不起。","id":"g088"},{"cat":"感謝道歉","kind":"tf","q":"道歉時，要說明自己做錯了什麼，會比只說「對不起」更有誠意。","a":"是","w":["否"],"ex":"說清楚，對方才知道你真的明白。","id":"g089"},{"cat":"感謝道歉","kind":"tf","q":"說了對不起，就一定要馬上被原諒。","a":"否","w":["是"],"ex":"原諒需要時間，我們要尊重對方的感受。","id":"g090"},{"cat":"感謝道歉","kind":"tf","q":"爸媽每天煮飯給我們吃，我們可以說「謝謝爸爸媽媽」。","a":"是","w":["否"],"ex":"感謝家人的付出，是很重要的習慣。","id":"g091"},{"cat":"感謝道歉","kind":"tf","q":"只有做了很大的事，才值得說謝謝。","a":"否","w":["是"],"ex":"小事也值得謝謝，例如幫你撿東西。","id":"g092"},{"cat":"感謝道歉","kind":"tf","q":"道歉的時候，一邊笑一邊說「對不起」是很誠懇的。","a":"否","w":["是"],"ex":"道歉時，態度要認真，對方才會感受到誠意。","id":"g093"},{"cat":"感謝道歉","kind":"tf","q":"別人道歉後，我們可以選擇原諒，讓彼此關係更好。","a":"是","w":["否"],"ex":"寬容是一種成熟的表現。","id":"g094"},{"cat":"感謝道歉","kind":"tf","q":"對幫助我們的人，用寫卡片的方式表達謝意，也是很棒的方法。","a":"是","w":["否"],"ex":"謝卡很有心意，也讓人難忘。","id":"g095"},{"cat":"感謝道歉","kind":"tf","q":"做錯事後，只要躲起來，就不需要道歉了。","a":"否","w":["是"],"ex":"勇敢面對、承認錯誤，才是負責的行為。","id":"g096"},{"cat":"感謝道歉","kind":"tf","q":"把功勞全部算在自己身上，不需要感謝幫忙的人。","a":"否","w":["是"],"ex":"分享功勞，感謝幫助你的人，大家才開心。","id":"g097"},{"cat":"感謝道歉","kind":"tf","q":"感謝老師的辛苦教導，也可以用認真學習來回報。","a":"是","w":["否"],"ex":"努力學習，就是對老師最好的感謝。","id":"g098"},{"cat":"感謝道歉","kind":"tf","q":"同學不小心弄壞我的文具，他道歉了，我可以說「沒關係」。","a":"是","w":["否"],"ex":"接受道歉，也可以提醒對方下次小心。","id":"g099"},{"cat":"感謝道歉","kind":"tf","q":"說「對不起」就是認輸，所以不能說。","a":"否","w":["是"],"ex":"道歉是勇敢和成熟，不是認輸。","id":"g100"},{"cat":"感謝道歉","kind":"tf","q":"被別人誇獎時，說「謝謝」是比較合適的回應。","a":"是","w":["否"],"ex":"接受稱讚，也是一種禮貌。","id":"g101"},{"cat":"感謝道歉","kind":"tf","q":"犯了錯被老師糾正，馬上找藉口說都是別人的錯，是好的做法。","a":"否","w":["是"],"ex":"先承認自己的錯，再想改善的方法。","id":"g102"},{"cat":"感謝道歉","kind":"tf","q":"鄰居伯伯幫忙撿到我的球，我可以說「謝謝伯伯」。","a":"是","w":["否"],"ex":"有禮貌的孩子，大家都喜歡。","id":"g103"},{"cat":"感謝道歉","kind":"tf","q":"道歉之後，還要想辦法補救，會讓對方更感受到誠意。","a":"是","w":["否"],"ex":"行動比言語更有力。","id":"g104"},{"cat":"感謝道歉","kind":"mc","q":"同學把掉在地上的筆撿起來還你，你可以說？","a":"謝謝你幫我撿起來","w":["喔","你很多事"],"ex":"簡單的謝謝，讓人心裡暖暖的。","id":"g105"},{"cat":"感謝道歉","kind":"mc","q":"你不小心踩到同學的腳，下列哪個道歉比較好？","a":"對不起，我踩到你了，你會痛嗎？","w":["哎呀，誰叫你站在這裡","沒事啦，又不會死"],"ex":"道歉加關心，最有誠意。","id":"g106"},{"cat":"感謝道歉","kind":"mc","q":"同學因為你亂丟垃圾生氣了，你可以怎麼做？","a":"說對不起，並把垃圾撿起來","w":["說他太小題大做","假裝沒聽到"],"ex":"道歉也要有行動。","id":"g107"},{"cat":"感謝道歉","kind":"mc","q":"媽媽幫你準備便當，你想表達感謝，下列哪種方式比較好？","a":"說「媽媽，便當好好吃，謝謝」","w":["只說「嗯」","說「又是這個喔」"],"ex":"具體的感謝，讓人更感動。","id":"g108"},{"cat":"感謝道歉","kind":"mc","q":"你弄壞了朋友的玩具，下列哪個做法比較負責？","a":"誠實道歉，並和他討論怎麼補償","w":["假裝不知道","說是別人弄壞的"],"ex":"負責任，才能保住友誼。","id":"g109"},{"cat":"感謝道歉","kind":"mc","q":"別人跟你道歉時，下列哪一種回應比較好？","a":"謝謝你跟我說，沒關係","w":["哼，不理你","你以為道歉就好嗎"],"ex":"接受道歉，彼此都能放下。","id":"g110"},{"cat":"感謝道歉","kind":"mc","q":"同學在你生病時帶來筆記，你可以怎麼做？","a":"說謝謝，並好好利用筆記","w":["說「你多事」","不理他"],"ex":"感謝同學的關心與幫助。","id":"g111"},{"cat":"感謝道歉","kind":"mc","q":"做錯事被老師看到，下列哪個回應比較好？","a":"說「對不起，我知道錯了」","w":["說「都是別人先開始的」","低下頭不理人"],"ex":"承認錯誤，是改過的第一步。","id":"g112"},{"cat":"感謝道歉","kind":"mc","q":"生日時收到朋友的卡片，你可以怎麼做？","a":"親自說謝謝，並回送祝福","w":["看完就丟掉","說卡片很醜"],"ex":"珍惜別人的心意。","id":"g113"},{"cat":"感謝道歉","kind":"mc","q":"不小心把同學的水瓶弄翻，下列做法最好的是？","a":"馬上說對不起，並幫忙擦乾","w":["假裝沒看到","責怪水瓶放得不好"],"ex":"立刻道歉並補救，最有誠意。","id":"g114"},{"cat":"感謝道歉","kind":"mc","q":"老師在畢業典禮上誇獎你，你可以怎麼說？","a":"謝謝老師的栽培","w":["還好啦，沒什麼","應該的啦"],"ex":"真誠感謝，是對老師最好的回應。","id":"g115"},{"cat":"感謝道歉","kind":"mc","q":"同學幫你在小組報告中做了很多事，你可以說？","a":"謝謝你這次幫了很大的忙","w":["這些本來就是你該做的","不用謝我"],"ex":"說出具體的感謝，更能鼓勵人。","id":"g116"},{"cat":"感謝道歉","kind":"mc","q":"想要感謝志工媽媽每天站在校門口，可以怎麼做？","a":"親口說「媽媽辛苦了，謝謝」","w":["低頭走過","說「你們好閒」"],"ex":"一句感謝，就能溫暖別人的一天。","id":"g117"},{"cat":"感謝道歉","kind":"mc","q":"你答應朋友的事做不到，下列哪種處理比較好？","a":"主動說對不起，並說明原因","w":["假裝忘記","躲著不見面"],"ex":"誠實面對，朋友才會信任你。","id":"g118"},{"cat":"感謝道歉","kind":"mc","q":"被同學提醒功課沒帶，你可以怎麼回應？","a":"謝謝你提醒我","w":["你管太多了","我知道啦，不用你說"],"ex":"感謝別人的善意提醒。","id":"g119"},{"cat":"感謝道歉","kind":"mc","q":"別人對你說「對不起」，但你還有點生氣，下列哪種說法比較好？","a":"謝謝你道歉，我需要一點時間","w":["不要再說了","我永遠不會原諒你"],"ex":"誠實說出感受，也尊重對方。","id":"g120"},{"cat":"感謝道歉","kind":"mc","q":"朋友送你一個你不太喜歡的禮物，你應該怎麼做？","a":"說謝謝，感謝他的心意","w":["說這個很醜","還給他"],"ex":"心意比禮物更重要。","id":"g121"},{"cat":"感謝道歉","kind":"mc","q":"同學誇獎你的畫畫得好，你可以怎麼回答？","a":"謝謝，我畫了很久","w":["沒有啦，你亂說","你的才不好看"],"ex":"謝謝是最簡單又好的回應。","id":"g122"},{"cat":"感謝道歉","kind":"mc","q":"不小心撞到老師，老師說沒關係，你可以怎麼說？","a":"謝謝老師，下次我會小心","w":["喔，太好了","我又不是故意的"],"ex":"感謝諒解，並提醒自己小心。","id":"g123"},{"cat":"感謝道歉","kind":"mc","q":"在小組中，有人幫你解決難題，你可以怎麼做？","a":"說謝謝，並記得下次幫助別人","w":["把功勞都攬在自己身上","假裝是自己想到的"],"ex":"互相幫助，團隊才強大。","id":"g124"},{"cat":"感謝道歉","kind":"mc","q":"媽媽生日時，你想表達感謝，下列哪種方法最有心意？","a":"寫卡片或做家事送給她","w":["不理她","只是說「生日快樂」，不做任何事"],"ex":"用心的行動，比金錢更珍貴。","id":"g125"},{"cat":"感謝道歉","kind":"mc","q":"同學對你說「謝謝」，下列哪個回答最溫暖？","a":"不客氣，需要的話隨時找我","w":["嗯","這本來就是你欠我的"],"ex":"溫暖的回應，讓友誼更好。","id":"g126"},{"cat":"感謝道歉","kind":"mc","q":"你誤會了同學，後來發現是你錯了，下列哪個做法最好？","a":"向他道歉，說明你的誤會","w":["裝作什麼都沒發生","繼續責怪他"],"ex":"有勇氣承認誤會，朋友才不會心裡難過。","id":"g127"},{"cat":"感謝道歉","kind":"mc","q":"在校外教學時，司機叔叔載我們回學校，下車時我可以說？","a":"謝謝叔叔，辛苦了","w":["快點開門啦","終於到了，好累"],"ex":"對辛苦的人說謝謝，很有禮貌。","id":"g128"},{"cat":"感謝道歉","kind":"mc","q":"你說了讓朋友難過的話，之後你覺得抱歉，可以怎麼做？","a":"找機會說對不起，並說出自己的想法","w":["等他自己氣消","在背後說他壞話"],"ex":"主動修補關係，讓友情更堅固。","id":"g129"},{"cat":"感謝道歉","kind":"mc","q":"別人為你做了一件小事，你想回報，下列哪個做法比較好？","a":"找機會也幫他一個忙","w":["完全不理他","要求更多"],"ex":"知恩圖報，讓善意循環。","id":"g130"},{"cat":"感謝道歉","kind":"mc","q":"你的小狗弄壞了鄰居的花，你可以怎麼做？","a":"向鄰居說對不起，並想辦法補償","w":["不承認，說是別人的狗","把花偷偷換掉不說"],"ex":"負責任是成熟的表現。","id":"g131"},{"cat":"感謝道歉","kind":"mc","q":"家人準備了你喜歡的晚餐，你可以怎麼做？","a":"說「謝謝，好好吃」","w":["只顧著看電視","說「怎麼不是別的」"],"ex":"感謝家人的用心。","id":"g132"},{"cat":"感謝道歉","kind":"mc","q":"被同學稱讚今天的衣服很漂亮，你可以怎麼說？","a":"謝謝，你的眼光也很好","w":["哼，我早就知道","沒有啦，很醜"],"ex":"友善回應，也讚美對方。","id":"g133"},{"cat":"感謝道歉","kind":"mc","q":"分組報告完成，你想感謝組員，下列哪句比較好？","a":"謝謝大家，這次合作很愉快","w":["這是我一個人完成的","你們都沒幫上忙"],"ex":"感謝夥伴，團隊精神才能延續。","id":"g134"},{"cat":"感謝道歉","kind":"mc","q":"在班上不小心說了別人的秘密，你可以怎麼做？","a":"向對方道歉，並且以後不再說","w":["說「誰叫你告訴我」","當作什麼都沒發生"],"ex":"守住秘密，才是真朋友。","id":"g135"},{"cat":"感謝道歉","kind":"mc","q":"同學幫你背書包到保健室，你想說謝謝，下列最好的方式是？","a":"謝謝你陪我，我好多了","w":["喔，好","你好慢"],"ex":"感謝陪伴，是溫暖的回饋。","id":"g136"},{"cat":"感謝道歉","kind":"mc","q":"被老師稱讚今天很認真，你可以怎麼說？","a":"謝謝老師，我會繼續努力","w":["都是我厲害","這沒什麼"],"ex":"謝謝加上努力，是很棒的回應。","id":"g137"},{"cat":"感謝道歉","kind":"mc","q":"想讓道歉更有誠意，下列哪個做法最重要？","a":"說出自己錯在哪裡，並想辦法改進","w":["只說一次對不起就轉頭走開","把錯推給別人"],"ex":"真誠與行動，才是誠意。","id":"g138"},{"cat":"感謝道歉","kind":"mc","q":"別人對你說了「謝謝」，你覺得很開心，可以怎麼做？","a":"微笑回應，記得這份溫暖","w":["不理他","說「你以後別再煩我」"],"ex":"善意被看見，心情會很好。","id":"g139"},{"cat":"傾聽表達","kind":"tf","q":"聽別人說話時，一邊玩手機，也算是專心傾聽。","a":"否","w":["是"],"ex":"專心傾聽，要看著對方，不分心。","id":"g140"},{"cat":"傾聽表達","kind":"tf","q":"傾聽的時候，不隨便打斷別人，是尊重對方的表現。","a":"是","w":["否"],"ex":"等對方說完，再說自己的想法。","id":"g141"},{"cat":"傾聽表達","kind":"tf","q":"聽到不同的意見，就要馬上反駁，才不會輸。","a":"否","w":["是"],"ex":"先聽完，再理性討論，比急著贏更重要。","id":"g142"},{"cat":"傾聽表達","kind":"tf","q":"表達想法時，用「我覺得……」開頭，比較不會讓人覺得被指責。","a":"是","w":["否"],"ex":"說出自己的感受，對方比較容易聽進去。","id":"g143"},{"cat":"傾聽表達","kind":"tf","q":"說話大聲，別人就一定會同意你。","a":"否","w":["是"],"ex":"好好說、有道理，才容易被接受。","id":"g144"},{"cat":"傾聽表達","kind":"tf","q":"聽朋友訴說煩惱時，點點頭、簡單回應，可以讓他知道你有在聽。","a":"是","w":["否"],"ex":"回應，是溫暖的傾聽。","id":"g145"},{"cat":"傾聽表達","kind":"tf","q":"別人說話很慢，我就可以催他快一點說。","a":"否","w":["是"],"ex":"耐心等待，是對別人的尊重。","id":"g146"},{"cat":"傾聽表達","kind":"tf","q":"有想法卻害羞不敢說，用寫的或畫的方式表達也可以。","a":"是","w":["否"],"ex":"表達的方式有很多種。","id":"g147"},{"cat":"傾聽表達","kind":"tf","q":"聽完別人的話，可以用自己的話複述一次，確認有沒有聽懂。","a":"是","w":["否"],"ex":"複述能避免誤會。","id":"g148"},{"cat":"傾聽表達","kind":"tf","q":"同學的想法和自己不同，就代表對方是錯的。","a":"否","w":["是"],"ex":"不同不等於錯，可以互相學習。","id":"g149"},{"cat":"傾聽表達","kind":"tf","q":"說話時，用嘲笑或諷刺的語氣，不會傷害別人。","a":"否","w":["是"],"ex":"語氣也會傷人，要好好說話。","id":"g150"},{"cat":"傾聽表達","kind":"tf","q":"當別人情緒激動時，先安靜聽他說完，通常比立刻講道理有幫助。","a":"是","w":["否"],"ex":"被聽見，情緒才會慢慢平復。","id":"g151"},{"cat":"傾聽表達","kind":"tf","q":"在小組討論，每個人輪流發言，可以讓大家的意見都被聽見。","a":"是","w":["否"],"ex":"輪流發言，是公平的表現。","id":"g152"},{"cat":"傾聽表達","kind":"tf","q":"只要我說的是事實，說話方式就不重要。","a":"否","w":["是"],"ex":"說話方式也很重要，好好說比較容易溝通。","id":"g153"},{"cat":"傾聽表達","kind":"tf","q":"有問題不敢問老師，是因為怕被笑，所以什麼都不要說最好。","a":"否","w":["是"],"ex":"勇敢提問，才有機會學到更多。","id":"g154"},{"cat":"傾聽表達","kind":"tf","q":"當我們不理解時，可以說「我不太懂，可以再說明一次嗎？」","a":"是","w":["否"],"ex":"禮貌地請教，是學習的好習慣。","id":"g155"},{"cat":"傾聽表達","kind":"mc","q":"同學在跟你說他的煩惱，下列哪一種做法比較好？","a":"專心聽，並適時回應","w":["一直看別的地方","打斷他說你的事"],"ex":"專心傾聽，讓對方感覺被重視。","id":"g156"},{"cat":"傾聽表達","kind":"mc","q":"要表達自己不同的意見時，下列哪一句比較合適？","a":"我有不同的想法，可以說說看嗎？","w":["你講的都是錯的","這種意見很蠢"],"ex":"禮貌表達，才能好好討論。","id":"g157"},{"cat":"傾聽表達","kind":"mc","q":"別人說話時，我們可以怎麼表現專心？","a":"看著對方、點頭回應","w":["一直轉筆玩東西","一直看窗外"],"ex":"眼神與動作，會讓對方覺得被在乎。","id":"g158"},{"cat":"傾聽表達","kind":"mc","q":"朋友說他今天很難過，你可以怎麼說？","a":"發生什麼事了？我陪你","w":["別想那麼多啦","你太愛哭了"],"ex":"關心，讓朋友覺得不孤單。","id":"g159"},{"cat":"傾聽表達","kind":"mc","q":"當你聽不懂老師說的內容，可以怎麼做？","a":"舉手請老師再說明","w":["假裝聽懂","影響別人的學習"],"ex":"勇敢提問，是學習的好習慣。","id":"g160"},{"cat":"傾聽表達","kind":"mc","q":"想請同學把音量放小一點，可以怎麼說？","a":"可以請你小聲一點嗎？謝謝","w":["你好吵，閉嘴","我要告訴老師"],"ex":"禮貌地請求，更容易被接受。","id":"g161"},{"cat":"傾聽表達","kind":"mc","q":"別人在發表意見時，你不同意，應該怎麼做？","a":"等他說完，再有禮貌地說出你的想法","w":["大聲打斷他","做鬼臉表示不屑"],"ex":"先聽完，再表達，是成熟的溝通。","id":"g162"},{"cat":"傾聽表達","kind":"mc","q":"朋友說了一件你覺得很好笑的事，但他其實很認真，你應該怎麼做？","a":"保持尊重，認真聽","w":["大聲笑他","轉頭和別人聊天"],"ex":"尊重別人的認真，不嘲笑。","id":"g163"},{"cat":"傾聽表達","kind":"mc","q":"在小組討論時，有同學一直不說話，你可以怎麼做？","a":"問他「你有什麼想法嗎？」","w":["不理他，繼續說","說他很沒用"],"ex":"邀請他說話，讓每個人都被聽見。","id":"g164"},{"cat":"傾聽表達","kind":"mc","q":"表達感受時，下列哪一種說法比較好？","a":"我覺得有點難過，因為你沒有等我","w":["你就是故意的","你都不在乎我"],"ex":"說出感受和原因，可以讓對方明白。","id":"g165"},{"cat":"傾聽表達","kind":"mc","q":"有同學在報告，你想問問題，應該怎麼做？","a":"等報告結束，再舉手提問","w":["一直打斷他","在台下大聲說他錯了"],"ex":"等待時機，是尊重報告的人。","id":"g166"},{"cat":"傾聽表達","kind":"mc","q":"聽朋友分享他的快樂事，你可以怎麼回應？","a":"哇，真棒！我替你開心","w":["那有什麼了不起","我的更厲害"],"ex":"分享喜悅，友誼更好。","id":"g167"},{"cat":"傾聽表達","kind":"mc","q":"對方說話速度很慢，你可以怎麼做？","a":"耐心等他說完","w":["替他把話說完","一直嘆氣"],"ex":"耐心傾聽，讓人安心表達。","id":"g168"},{"cat":"傾聽表達","kind":"mc","q":"老師在說明規則時，同學小聲討論，這時你可以怎麼做？","a":"等老師說完，再討論","w":["大聲插話","做自己的事"],"ex":"先專心聽，再提問。","id":"g169"},{"cat":"傾聽表達","kind":"mc","q":"朋友說的事和你想的不同，你可以怎麼說？","a":"原來你是這樣想的，我可以說說我的想法嗎？","w":["你錯了","你根本不懂"],"ex":"先理解，再說明，比較容易溝通。","id":"g170"},{"cat":"傾聽表達","kind":"mc","q":"想要拒絕別人的邀約，下列哪一種說法比較好？","a":"謝謝你邀我，可是我這次不方便","w":["你很煩，不要找我","不要，我才不去"],"ex":"禮貌拒絕，才不傷感情。","id":"g171"},{"cat":"傾聽表達","kind":"mc","q":"有同學對你生氣大聲說話，你可以怎麼做？","a":"深呼吸，先聽他說完","w":["大聲吼回去","馬上走開不理人"],"ex":"冷靜聆聽，有助於化解衝突。","id":"g172"},{"cat":"傾聽表達","kind":"mc","q":"如果沒聽清楚對方說的話，可以怎麼做？","a":"請對方再說一次","w":["假裝聽到了","猜一猜就回答"],"ex":"確認清楚，才不會誤會。","id":"g173"},{"cat":"傾聽表達","kind":"mc","q":"有人跟你分享心事，並請你保密，你可以怎麼做？","a":"保守秘密，不隨便告訴別人","w":["立刻告訴其他朋友","在班上公開說"],"ex":"信守承諾，是朋友間最重要的信任。","id":"g174"},{"cat":"傾聽表達","kind":"mc","q":"有人分享作品給你看，你可以怎麼回應？","a":"說出你看到的優點，並謝謝他分享","w":["說「這很普通」","直接走開"],"ex":"真誠的回饋，讓對方更有信心。","id":"g175"},{"cat":"傾聽表達","kind":"mc","q":"想邀請別人一起玩，下列哪一句比較合適？","a":"要不要一起玩？","w":["你快點過來","你一定要跟我玩"],"ex":"詢問而非命令，比較尊重對方。","id":"g176"},{"cat":"傾聽表達","kind":"mc","q":"同學提出的想法和你不同，你可以怎麼做？","a":"先聽聽他的理由","w":["立刻說他不對","不理他的想法"],"ex":"傾聽理由，可以讓你學到新觀點。","id":"g177"},{"cat":"傾聽表達","kind":"mc","q":"表達意見時，下列哪一種語氣比較好？","a":"平穩、有禮貌","w":["大聲、帶刺","冷冷地諷刺"],"ex":"語氣溫和，對方才聽得進去。","id":"g178"},{"cat":"傾聽表達","kind":"mc","q":"當你不同意別人的做法時，應該怎麼表達？","a":"提出自己的建議，並說明原因","w":["直接說「你很蠢」","在背後批評他"],"ex":"建設性的意見，才能幫助彼此。","id":"g179"},{"cat":"傾聽表達","kind":"mc","q":"同學用很小的聲音回答問題，你可以怎麼做？","a":"請他再說一次，或靠近一點聽","w":["嘲笑他聲音小","大聲說他講太小聲"],"ex":"給予支持，讓膽小的人更有勇氣。","id":"g180"},{"cat":"傾聽表達","kind":"mc","q":"你想告訴朋友一個壞消息，可以怎麼說比較好？","a":"我想跟你說一件事，希望你別太難過","w":["你聽了不要哭喔，哈哈","說話時一直笑他"],"ex":"考慮對方感受，說話更有溫度。","id":"g181"},{"cat":"傾聽表達","kind":"mc","q":"小組討論時，有人提出很棒的想法，你可以怎麼做？","a":"稱讚他，並一起把想法完成","w":["說「那是我先想到的」","不理會他的想法"],"ex":"欣賞別人，團隊才更強大。","id":"g182"},{"cat":"傾聽表達","kind":"mc","q":"有人請你幫忙，但你現在真的有事，可以怎麼說？","a":"現在我有事，晚一點可以幫你，好嗎？","w":["不要，別煩我","我才不幫你"],"ex":"說明原因，並提出替代方案。","id":"g183"},{"cat":"傾聽表達","kind":"mc","q":"有人在你說話時一直看手機，你的感受可能是？","a":"被忽視、不被尊重","w":["很開心","很被重視"],"ex":"專心聆聽，是基本的禮貌。","id":"g184"},{"cat":"傾聽表達","kind":"mc","q":"聽到別人說了讓你不舒服的話，下列哪一種處理比較合適？","a":"冷靜地告訴他你的感受","w":["大聲罵回去","在背後說他壞話"],"ex":"表達感受，比情緒爆發更有效。","id":"g185"},{"cat":"傾聽表達","kind":"mc","q":"同學做錯事，你想提醒他，下列哪一種做法比較好？","a":"私下輕聲告訴他","w":["在大家面前大聲指責","把他的錯告訴全班"],"ex":"顧及面子，更容易讓人接受。","id":"g186"},{"cat":"傾聽表達","kind":"mc","q":"如何讓別人更容易聽懂你的話？","a":"說話清楚、慢慢說","w":["越快越好","只用手勢比，不說話"],"ex":"清楚、有條理，別人才聽得懂。","id":"g187"},{"cat":"傾聽表達","kind":"mc","q":"朋友告訴你他的夢想，你可以怎麼回應？","a":"為他加油，並說出你的支持","w":["說他不可能成功","嘲笑他的夢想"],"ex":"支持與鼓勵，讓夢想更有力量。","id":"g188"},{"cat":"傾聽表達","kind":"mc","q":"你想說的話很重要，但別人正在說話，你應該怎麼做？","a":"等他說完，再舉手或開口","w":["立刻大聲插嘴","用力拍桌子"],"ex":"耐心等待，是基本的禮貌。","id":"g189"},{"cat":"傾聽表達","kind":"mc","q":"你和同學意見不同，無法決定時，可以怎麼做？","a":"輪流表達，一起想出折衷的辦法","w":["大聲吵架","找別的同學來幫你吵"],"ex":"彼此退一步，才能找到共同方案。","id":"g190"},{"cat":"傾聽表達","kind":"mc","q":"你想告訴老師你不舒服，下列哪一種做法最好？","a":"舉手，輕聲說明哪裡不舒服","w":["趴在桌上一直不說","大聲尖叫"],"ex":"清楚說明，老師才能幫上忙。","id":"g191"},{"cat":"同理情緒","kind":"tf","q":"同理心就是站在別人的立場，想想他的感受。","a":"是","w":["否"],"ex":"換位思考，是同理心的核心。","id":"g192"},{"cat":"同理情緒","kind":"tf","q":"看到同學跌倒哭了，說「這有什麼好哭的」是有同理心的表現。","a":"否","w":["是"],"ex":"先關心他的感受與傷勢。","id":"g193"},{"cat":"同理情緒","kind":"tf","q":"每個人遇到相同的事，感受都一定一樣。","a":"否","w":["是"],"ex":"每個人的感受不同，要尊重。","id":"g194"},{"cat":"同理情緒","kind":"tf","q":"生氣、難過、害怕都是正常的情緒，不需要覺得羞愧。","a":"是","w":["否"],"ex":"情緒沒有好壞，重要的是怎麼處理。","id":"g195"},{"cat":"同理情緒","kind":"tf","q":"只有「開心」才是好情緒，其他情緒都是不好的。","a":"否","w":["是"],"ex":"每種情緒都有它的功能，學會覺察最重要。","id":"g196"},{"cat":"同理情緒","kind":"tf","q":"朋友難過時，陪在他身邊安靜地聽，也是一種安慰。","a":"是","w":["否"],"ex":"有時候陪伴比說話更有力量。","id":"g197"},{"cat":"同理情緒","kind":"tf","q":"看到別人有困難，卻因為不關我的事就不理，是有同理心的做法。","a":"否","w":["是"],"ex":"同理心讓我們願意伸出援手。","id":"g198"},{"cat":"同理情緒","kind":"tf","q":"當我們說出自己的感受，別人比較容易理解我們。","a":"是","w":["否"],"ex":"表達感受，是溝通的第一步。","id":"g199"},{"cat":"同理情緒","kind":"tf","q":"男生不可以哭，女生才可以哭。","a":"否","w":["是"],"ex":"不論性別，任何人難過都可以哭，哭是很自然的情緒表達。","id":"g200"},{"cat":"同理情緒","kind":"tf","q":"同學考試考不好，我說「你怎麼那麼笨」，是在鼓勵他。","a":"否","w":["是"],"ex":"責備不是鼓勵，應該說「我們一起想辦法」。","id":"g201"},{"cat":"同理情緒","kind":"tf","q":"情緒就像天氣，會來也會走。","a":"是","w":["否"],"ex":"情緒是暫時的，我們可以學會等待。","id":"g202"},{"cat":"同理情緒","kind":"tf","q":"別人心情不好，我也要馬上讓他變開心，才算是好朋友。","a":"否","w":["是"],"ex":"尊重他的情緒，陪伴比急著改變他更重要。","id":"g203"},{"cat":"同理情緒","kind":"tf","q":"看到別人哭，先問「你還好嗎？」是關心的表現。","a":"是","w":["否"],"ex":"問候的話，可以讓對方感覺被在乎。","id":"g204"},{"cat":"同理情緒","kind":"tf","q":"同學的作品被嘲笑，我雖然沒有嘲笑，但也不需要說什麼。","a":"否","w":["是"],"ex":"我們可以勇敢站出來，說出尊重的話。","id":"g205"},{"cat":"同理情緒","kind":"tf","q":"做錯事心裡覺得難受，是因為我們有良心與同理心。","a":"是","w":["否"],"ex":"愧疚感是良心的提醒。","id":"g206"},{"cat":"同理情緒","kind":"tf","q":"心情不好時，把氣出在別人身上是比較好的解決方式。","a":"否","w":["是"],"ex":"可以找方法安靜下來，不傷害別人。","id":"g207"},{"cat":"同理情緒","kind":"tf","q":"當我們覺得緊張時，深呼吸可以幫助自己放鬆。","a":"是","w":["否"],"ex":"深呼吸能讓身體和心情慢慢平靜。","id":"g208"},{"cat":"同理情緒","kind":"tf","q":"只要我心情不好，別人就應該要讓著我。","a":"否","w":["是"],"ex":"每個人都有情緒，我們要學會照顧自己的情緒。","id":"g209"},{"cat":"同理情緒","kind":"tf","q":"同學的家人生病了，他可能心情比較沉重，我可以多關心他。","a":"是","w":["否"],"ex":"體貼別人的處境，是同理心的表現。","id":"g210"},{"cat":"同理情緒","kind":"tf","q":"「你不要難過了」是最好的安慰方式，不需要聽對方說原因。","a":"否","w":["是"],"ex":"先傾聽，讓對方把感受說出來更有幫助。","id":"g211"},{"cat":"同理情緒","kind":"tf","q":"看到別人開心，我也跟著開心，是一種分享快樂的同理心。","a":"是","w":["否"],"ex":"快樂可以分享，也會加倍。","id":"g212"},{"cat":"同理情緒","kind":"tf","q":"情緒激動時，立刻做決定通常比較好。","a":"否","w":["是"],"ex":"先冷靜，再決定，才不會後悔。","id":"g213"},{"cat":"同理情緒","kind":"tf","q":"說出自己的情緒，例如「我現在很生氣」，有助於讓自己平靜。","a":"是","w":["否"],"ex":"說出來，情緒就比較容易被理解。","id":"g214"},{"cat":"同理情緒","kind":"tf","q":"有人在你說「我好緊張」時回答「這有什麼好緊張的」，是合適的安慰。","a":"否","w":["是"],"ex":"應該說「緊張是正常的，我們一起面對」。","id":"g215"},{"cat":"同理情緒","kind":"tf","q":"同學因為搬家要轉學，可能會捨不得，我可以陪他聊聊。","a":"是","w":["否"],"ex":"陪伴與傾聽，是最溫柔的支持。","id":"g216"},{"cat":"同理情緒","kind":"tf","q":"別人給你建議時，你覺得不舒服，也要馬上生氣回嘴。","a":"否","w":["是"],"ex":"可以先冷靜，說出你的感受。","id":"g217"},{"cat":"同理情緒","kind":"tf","q":"有時候，我們的心情會因為睡不夠、肚子餓而變得不好。","a":"是","w":["否"],"ex":"照顧身體，也是照顧情緒。","id":"g218"},{"cat":"同理情緒","kind":"tf","q":"感到孤單的時候，找信任的人聊聊，可以讓心情好一點。","a":"是","w":["否"],"ex":"說出來，不再一個人承擔。","id":"g219"},{"cat":"同理情緒","kind":"tf","q":"看到別人哭，笑他愛哭，才能讓他變堅強。","a":"否","w":["是"],"ex":"嘲笑只會讓人更難過。","id":"g220"},{"cat":"同理情緒","kind":"tf","q":"每個人都可能有情緒低落的時候，我們可以給彼此一些時間。","a":"是","w":["否"],"ex":"體諒與耐心，是友誼的養分。","id":"g221"},{"cat":"同理情緒","kind":"mc","q":"同學今天一直低著頭，看起來不太開心，你可以怎麼做？","a":"輕聲問他「你還好嗎？」","w":["直接問他為什麼那麼奇怪","假裝沒看到"],"ex":"關心要溫柔，不要追問太多。","id":"g222"},{"cat":"同理情緒","kind":"mc","q":"別人在難過時，下列哪句話比較有同理心？","a":"我知道你一定很難過","w":["你太誇張了","這又不是什麼大事"],"ex":"接納對方的感受，是同理心的開始。","id":"g223"},{"cat":"同理情緒","kind":"mc","q":"看到同學的作品被別人踩壞了，你覺得他可能是什麼感受？","a":"難過、生氣","w":["開心","沒感覺"],"ex":"換位思考，才能理解對方。","id":"g224"},{"cat":"同理情緒","kind":"mc","q":"當你感到非常生氣時，下列哪一種處理方式比較好？","a":"先離開現場深呼吸，等心情平靜","w":["大聲罵人","打人出氣"],"ex":"先冷靜，才不會做出後悔的事。","id":"g225"},{"cat":"同理情緒","kind":"mc","q":"朋友告訴你他很緊張，要上台報告，你可以怎麼說？","a":"我陪你練習，你一定可以的","w":["你一定會失敗","緊張就不要去"],"ex":"鼓勵與支持，是最好的朋友。","id":"g226"},{"cat":"同理情緒","kind":"mc","q":"看到有人被孤立，一個人坐在角落，你可以怎麼做？","a":"主動邀請他一起玩","w":["假裝沒看到","在旁邊嘲笑他"],"ex":"善意邀請，可以讓他感受到溫暖。","id":"g227"},{"cat":"同理情緒","kind":"mc","q":"同學因為考試失利而哭，你可以怎麼說？","a":"沒關係，我們一起看看哪裡可以改進","w":["你太笨了","哭有什麼用"],"ex":"鼓勵與陪伴，比責備更有效。","id":"g228"},{"cat":"同理情緒","kind":"mc","q":"心情不好時，下列哪一種方法比較健康？","a":"找信任的人聊聊","w":["摔東西","把氣出在別人身上"],"ex":"適當宣洩，不傷害別人。","id":"g229"},{"cat":"同理情緒","kind":"mc","q":"朋友說他失去了心愛的寵物，你可以怎麼回應？","a":"我很遺憾，我可以陪你","w":["不過就是一隻小動物","再買一隻就好了"],"ex":"尊重他的悲傷，才是真正的關心。","id":"g230"},{"cat":"同理情緒","kind":"mc","q":"你發現朋友的心情很差，但他不想說，你可以怎麼做？","a":"告訴他「我在這裡，如果你想說就說」","w":["一直逼他說","不理他"],"ex":"尊重對方的步調，也讓他知道你在。","id":"g231"},{"cat":"同理情緒","kind":"mc","q":"當你很難過時，下列哪一種想法對自己比較好？","a":"難過是正常的，會過去的","w":["我一定很沒用","我不值得被愛"],"ex":"善待自己，情緒才容易恢復。","id":"g232"},{"cat":"同理情緒","kind":"mc","q":"看到同學開心地分享好消息，你可以怎麼回應？","a":"恭喜你，我替你高興","w":["那有什麼了不起","我的更好"],"ex":"分享喜悅，是同理心的表現。","id":"g233"},{"cat":"同理情緒","kind":"mc","q":"情緒很激動，快要大哭時，下列哪一種方法可以幫助自己？","a":"找安靜的地方深呼吸","w":["大聲尖叫","丟東西"],"ex":"深呼吸，可以讓身體放鬆。","id":"g234"},{"cat":"同理情緒","kind":"mc","q":"你和朋友吵架了，覺得很難受，這時可以怎麼做？","a":"找個時間和他好好談談","w":["永遠不理他","在背後說他壞話"],"ex":"談一談，有機會化解誤會。","id":"g235"},{"cat":"同理情緒","kind":"mc","q":"看到有人被罵得很傷心，你可以怎麼做？","a":"陪他走開，安慰他","w":["在旁邊看熱鬧","跟著一起罵"],"ex":"站在對方的立場，給他支持。","id":"g236"},{"cat":"同理情緒","kind":"mc","q":"害怕上台說話，可以怎麼讓自己比較不緊張？","a":"多練習、深呼吸","w":["直接放棄","在台上一直想著失敗"],"ex":"準備與呼吸，可以讓人更有信心。","id":"g237"},{"cat":"同理情緒","kind":"mc","q":"別人對你說話太大聲，你覺得不舒服，可以怎麼做？","a":"冷靜地說「你這樣說話，我有點不舒服」","w":["大聲回罵","直接走開不理人"],"ex":"說出感受，可以讓對方改變。","id":"g238"},{"cat":"同理情緒","kind":"mc","q":"同學生病請假回來，你可以怎麼說？","a":"你回來了，身體好點了嗎？","w":["你怎麼這麼久沒來","你的功課都沒做"],"ex":"關心對方，是同學間的溫暖。","id":"g239"},{"cat":"同理情緒","kind":"mc","q":"你做錯事，心裡覺得很愧疚，可以怎麼辦？","a":"勇敢道歉並想辦法改善","w":["假裝沒事","責怪別人"],"ex":"面對錯誤，才能放下愧疚。","id":"g240"},{"cat":"同理情緒","kind":"mc","q":"你發現朋友在哭，下列哪個行動最適合？","a":"遞面紙、陪他一下","w":["嘲笑他愛哭","當作沒看到"],"ex":"溫柔的小動作，也是安慰。","id":"g241"},{"cat":"同理情緒","kind":"mc","q":"看到同學因為失去心愛的東西而難過，你可以怎麼做？","a":"幫他一起找，並安慰他","w":["說「那只是東西而已」","不理他"],"ex":"一起找，讓他覺得不孤單。","id":"g242"},{"cat":"同理情緒","kind":"mc","q":"朋友被別人誤會，很難過，你可以怎麼做？","a":"聽他說，並幫他澄清","w":["跟著一起誤會他","不理他"],"ex":"相信朋友，也幫他說明。","id":"g243"},{"cat":"同理情緒","kind":"mc","q":"心情很差，不想說話時，下列哪個做法比較好？","a":"告訴大人「我現在需要一點安靜」","w":["對人大吼","砸東西"],"ex":"適當表達需求，比爆發更好。","id":"g244"},{"cat":"同理情緒","kind":"mc","q":"你看到弟弟妹妹因為玩具被搶而哭，可以怎麼做？","a":"安慰他，並幫他把玩具要回來","w":["笑他沒用","不理他"],"ex":"關懷弟妹，是照顧的表現。","id":"g245"},{"cat":"同理情緒","kind":"mc","q":"聽到朋友說「我今天心情很糟」，下列哪個回答比較好？","a":"發生什麼事了？想聊嗎？","w":["那你自己去解決","你太愛抱怨"],"ex":"主動關心，才有機會幫忙。","id":"g246"},{"cat":"同理情緒","kind":"mc","q":"感到害怕時，下列哪一種方式可以幫助自己？","a":"告訴信任的大人，並深呼吸","w":["一個人躲起來不說","假裝不害怕"],"ex":"說出來，才會有人幫助你。","id":"g247"},{"cat":"同理情緒","kind":"mc","q":"同學因為某件事很生氣，你可以怎麼做？","a":"讓他先冷靜，再聽他說","w":["跟他一起罵人","叫他閉嘴"],"ex":"先接納情緒，再解決問題。","id":"g248"},{"cat":"同理情緒","kind":"mc","q":"有人跟你說「我覺得很孤單」，你可以怎麼回應？","a":"謝謝你告訴我，我陪你","w":["你想太多了","那是你自己的問題"],"ex":"傾聽與陪伴，可以減少孤單。","id":"g249"},{"cat":"同理情緒","kind":"mc","q":"看到班上有同學常常一個人，你可以怎麼做？","a":"邀請他加入遊戲或分組","w":["不管他","取笑他"],"ex":"主動關心，讓班級更溫暖。","id":"g250"},{"cat":"同理情緒","kind":"mc","q":"下列哪一個詞，可以形容「覺得別人的難過就像自己的難過」？","a":"同理心","w":["嫉妒","驕傲"],"ex":"同理心，是感受別人感受的能力。","id":"g251"},{"cat":"同理情緒","kind":"mc","q":"朋友告訴你他得了第一名，但你自己這次沒考好，你可以怎麼做？","a":"真心恭喜他，也告訴自己繼續努力","w":["說他一定作弊","不理他"],"ex":"為別人高興，也是成熟的表現。","id":"g252"},{"cat":"同理情緒","kind":"mc","q":"你不小心說了傷人的話，下列哪個做法比較好？","a":"馬上道歉，並說明你不是有意的","w":["當作沒說過","說「是你太敏感」"],"ex":"誠懇道歉，可以修補傷口。","id":"g253"},{"cat":"同理情緒","kind":"mc","q":"你很生氣，想用力摔門時，可以先做什麼？","a":"數到十，深呼吸","w":["大力摔門","大吼大叫"],"ex":"暫停一下，可以避免做出不好的行為。","id":"g254"},{"cat":"同理情緒","kind":"mc","q":"同學因為家裡有事，上課看起來很疲倦，你可以怎麼做？","a":"不吵他，下課時問問他需不需要幫忙","w":["說他不認真","在背後說他懶惰"],"ex":"體貼對方的狀況，是同理心的表現。","id":"g255"},{"cat":"同理情緒","kind":"mc","q":"在你很開心時，朋友心情不好，你可以怎麼做？","a":"收斂一點，先陪陪他","w":["大聲炫耀你的好事","叫他別掃興"],"ex":"體貼別人的心情，是成熟的表現。","id":"g256"},{"cat":"同理情緒","kind":"mc","q":"有同學因為膽小不敢上台，你可以怎麼做？","a":"給他鼓勵，並陪他一起練習","w":["取笑他膽小","逼他上台"],"ex":"溫暖的支持，讓膽小的人慢慢進步。","id":"g257"},{"cat":"同理情緒","kind":"mc","q":"有人跟你說他很害怕打針，你可以怎麼說？","a":"很多人都會怕，我陪你去","w":["哈哈，怕什麼","你很沒用"],"ex":"尊重他的害怕，就是同理心。","id":"g258"},{"cat":"同理情緒","kind":"mc","q":"當你發現自己嫉妒別人時，下列哪種處理比較好？","a":"承認自己有這種感覺，並想辦法努力","w":["說別人壞話","故意搗亂"],"ex":"覺察情緒，轉化成進步的力量。","id":"g259"},{"cat":"情緒調節","kind":"tf","q":"生氣時，先深呼吸三次，可以幫助自己冷靜。","a":"是","w":["否"],"ex":"呼吸能讓身體放鬆，情緒也會變穩。","id":"g260"},{"cat":"情緒調節","kind":"tf","q":"生氣時，把手邊的東西摔壞，可以解決問題。","a":"否","w":["是"],"ex":"摔東西只會製造更多麻煩。","id":"g261"},{"cat":"情緒調節","kind":"tf","q":"情緒不好時，運動、畫畫、聽音樂，都是不傷害別人的紓壓方式。","a":"是","w":["否"],"ex":"找到適合自己的方法很重要。","id":"g262"},{"cat":"情緒調節","kind":"tf","q":"對於一直失敗的事，乾脆放棄比較好，不用再試。","a":"否","w":["是"],"ex":"失敗是學習的機會，可以換個方法再試。","id":"g263"},{"cat":"情緒調節","kind":"tf","q":"遇到挫折時，找家人或朋友說說，可以讓心情輕鬆一點。","a":"是","w":["否"],"ex":"說出來，就不用一個人扛。","id":"g264"},{"cat":"情緒調節","kind":"tf","q":"別人說我不好，我就一定要馬上反擊。","a":"否","w":["是"],"ex":"先冷靜，不一定要立刻回應。","id":"g265"},{"cat":"情緒調節","kind":"tf","q":"考試考不好，是在提醒我們哪裡需要加強。","a":"是","w":["否"],"ex":"把失敗當成學習的線索。","id":"g266"},{"cat":"情緒調節","kind":"tf","q":"遇到壓力時，什麼都不說，一直悶在心裡最好。","a":"否","w":["是"],"ex":"壓力需要出口，說出來比較好。","id":"g267"},{"cat":"情緒調節","kind":"tf","q":"生氣時說出的話，可能會傷到別人，所以先冷靜很重要。","a":"是","w":["否"],"ex":"冷靜後再說，才不會說出後悔的話。","id":"g268"},{"cat":"情緒調節","kind":"tf","q":"有人惹你生氣，你一定要打他才能出氣。","a":"否","w":["是"],"ex":"暴力會帶來更多問題，可以找大人幫忙。","id":"g269"},{"cat":"情緒調節","kind":"tf","q":"心情不好時，可以給自己一點時間，慢慢調整。","a":"是","w":["否"],"ex":"不用急著好起來，一步一步來。","id":"g270"},{"cat":"情緒調節","kind":"tf","q":"感到焦慮時，做個簡單的伸展或散步，有助於放鬆。","a":"是","w":["否"],"ex":"動一動，身體放鬆，心情也會跟著好。","id":"g271"},{"cat":"情緒調節","kind":"tf","q":"別人比我強，我就應該討厭他。","a":"否","w":["是"],"ex":"欣賞別人，也能讓自己進步。","id":"g272"},{"cat":"情緒調節","kind":"tf","q":"做完事情覺得很累時，休息一下是正常的。","a":"是","w":["否"],"ex":"適度休息，才能走更遠。","id":"g273"},{"cat":"情緒調節","kind":"tf","q":"看到成績單不理想，就覺得自己一無是處。","a":"否","w":["是"],"ex":"成績不等於全部，我們還有許多優點。","id":"g274"},{"cat":"情緒調節","kind":"tf","q":"當我們很生氣時，數到十再回答，可以避免說出傷人的話。","a":"是","w":["否"],"ex":"暫停一下，是控制情緒的好方法。","id":"g275"},{"cat":"情緒調節","kind":"tf","q":"害怕的時候，告訴信任的大人，可以讓我們得到幫助。","a":"是","w":["否"],"ex":"說出害怕，才有人可以幫你。","id":"g276"},{"cat":"情緒調節","kind":"tf","q":"越是壓抑情緒，越能成為堅強的人。","a":"否","w":["是"],"ex":"適當表達情緒，才是健康的做法。","id":"g277"},{"cat":"情緒調節","kind":"tf","q":"運動可以幫助釋放壓力，也讓心情變好。","a":"是","w":["否"],"ex":"運動會讓身體產生快樂的感覺。","id":"g278"},{"cat":"情緒調節","kind":"tf","q":"心情不好時，大吃大喝可以解決所有問題。","a":"否","w":["是"],"ex":"吃只能暫時分心，要找真正的解決方法。","id":"g279"},{"cat":"情緒調節","kind":"tf","q":"每個人都會有想放棄的時候，休息一下再繼續也沒關係。","a":"是","w":["否"],"ex":"休息不是放棄，是為了走更遠。","id":"g280"},{"cat":"情緒調節","kind":"tf","q":"輸了比賽就應該生氣、責怪別人。","a":"否","w":["是"],"ex":"輸了也要學習接受，下次再努力。","id":"g281"},{"cat":"情緒調節","kind":"tf","q":"當我們覺得壓力很大時，把事情寫下來可以讓腦袋更清楚。","a":"是","w":["否"],"ex":"寫下來，有助於整理想法。","id":"g282"},{"cat":"情緒調節","kind":"tf","q":"遇到困難就逃避，困難自己就會消失。","a":"否","w":["是"],"ex":"逃避只會讓問題累積，要一步一步面對。","id":"g283"},{"cat":"情緒調節","kind":"tf","q":"感到難過時，可以允許自己哭一哭，把情緒釋放出來。","a":"是","w":["否"],"ex":"眼淚也是情緒的出口。","id":"g284"},{"cat":"情緒調節","kind":"mc","q":"當你很生氣的時候，最先應該做什麼？","a":"深呼吸，讓自己冷靜","w":["大吼大叫","摔東西"],"ex":"冷靜後，才能好好處理。","id":"g285"},{"cat":"情緒調節","kind":"mc","q":"考試前覺得很緊張，下列哪一種方法有幫助？","a":"深呼吸、提醒自己已經準備好了","w":["一直想著會考不好","不吃不睡"],"ex":"正向的自我對話，可以減少緊張。","id":"g286"},{"cat":"情緒調節","kind":"mc","q":"被人誤會心裡很委屈，可以怎麼做？","a":"找適當的時間說明清楚","w":["在心裡生悶氣一輩子","大罵對方"],"ex":"說明事實，才有機會化解誤會。","id":"g287"},{"cat":"情緒調節","kind":"mc","q":"下課和同學玩遊戲輸了，你很不甘心，可以怎麼做？","a":"恭喜對方，並想想下次怎麼贏","w":["大哭大鬧","破壞遊戲"],"ex":"輸贏都是學習，保持運動家精神。","id":"g288"},{"cat":"情緒調節","kind":"mc","q":"壓力很大的時候，下列哪一種方式比較好？","a":"和信任的人聊聊、做喜歡的事","w":["一個人偷偷生氣","傷害自己"],"ex":"適當的紓壓方式，讓人更有力量。","id":"g289"},{"cat":"情緒調節","kind":"mc","q":"同學不小心弄壞你的東西，你很生氣，可以怎麼做？","a":"先深呼吸，再告訴他你的感受","w":["大聲罵他","搶他的東西作為報復"],"ex":"冷靜表達感受，比報復有用。","id":"g290"},{"cat":"情緒調節","kind":"mc","q":"發現自己很容易生氣，可以怎麼改善？","a":"練習深呼吸、學會暫停","w":["生氣就要大吼","責怪別人惹你生氣"],"ex":"練習控制情緒，是成長的一部分。","id":"g291"},{"cat":"情緒調節","kind":"mc","q":"感到焦慮時，下列哪個方法比較能讓自己放鬆？","a":"聽音樂、散步、深呼吸","w":["不停想壞事","熬夜不睡覺"],"ex":"放鬆活動能讓大腦休息。","id":"g292"},{"cat":"情緒調節","kind":"mc","q":"被老師糾正感到難過時，你可以怎麼想？","a":"老師是希望我進步，我可以改進","w":["老師討厭我","我是個壞學生"],"ex":"換個角度，比較容易接受。","id":"g293"},{"cat":"情緒調節","kind":"mc","q":"我們可以用哪種方式把心裡的話整理出來？","a":"寫日記或畫圖","w":["對著牆壁打拳","摔門離開"],"ex":"創作與書寫，是溫和的表達方式。","id":"g294"},{"cat":"情緒調節","kind":"mc","q":"朋友突然不理你，你覺得難過，可以怎麼做？","a":"找機會問他發生了什麼事","w":["也不理他，報復他","在背後說他壞話"],"ex":"溝通，才能找出原因。","id":"g295"},{"cat":"情緒調節","kind":"mc","q":"比賽前緊張，下列哪句話能幫助你？","a":"我已經盡力準備了，慢慢來就好","w":["我一定會失敗","我不要比了"],"ex":"正向的想法，可以減少壓力。","id":"g296"},{"cat":"情緒調節","kind":"mc","q":"遇到難題時，覺得很挫折，可以怎麼做？","a":"休息一下，再換個方法試試看","w":["立刻放棄","生氣丟書"],"ex":"調整心情，再重新挑戰。","id":"g297"},{"cat":"情緒調節","kind":"mc","q":"被別人嘲笑時覺得很生氣，下列哪個做法比較好？","a":"冷靜走開，告訴老師或信任的大人","w":["馬上動手打人","大聲回罵"],"ex":"尋求協助，比暴力更有效。","id":"g298"},{"cat":"情緒調節","kind":"mc","q":"你很想哭，但是在教室裡，可以怎麼做？","a":"請老師讓你到安靜的地方休息一下","w":["憋著不說","大吼大叫"],"ex":"適當求助，讓自己好過一點。","id":"g299"},{"cat":"情緒調節","kind":"mc","q":"覺得自己不夠好，常常自責，下列哪一種想法比較健康？","a":"我也有優點，可以慢慢進步","w":["我什麼都做不好","別人都比我強"],"ex":"善待自己，才會有力量前進。","id":"g300"},{"cat":"情緒調節","kind":"mc","q":"心情很低落時，下列哪個活動比較有幫助？","a":"到戶外走走、曬太陽","w":["關在房間不見人","一直滑手機"],"ex":"運動與陽光，有助於心情。","id":"g301"},{"cat":"情緒調節","kind":"mc","q":"在比賽中沒有得到名次，你可以怎麼想？","a":"我已經努力了，下次可以更好","w":["我再也不參加了","都是別人的錯"],"ex":"享受過程，比名次更重要。","id":"g302"},{"cat":"情緒調節","kind":"mc","q":"被朋友取笑你的名字，你覺得難過，可以怎麼做？","a":"冷靜地告訴他你不喜歡這樣","w":["也取笑他的名字","不吃飯不說話"],"ex":"說出感受，對方才知道界線。","id":"g303"},{"cat":"情緒調節","kind":"mc","q":"同學考得比你好，你有點嫉妒，可以怎麼做？","a":"恭喜他，並請教他的方法","w":["說他一定作弊","故意不理他"],"ex":"學習別人的優點，讓自己進步。","id":"g304"},{"cat":"情緒調節","kind":"mc","q":"遇到想要放棄的時候，下列哪一句話比較能給自己力量？","a":"再試一次，也許就成功了","w":["我就是不行","算了，不要努力了"],"ex":"鼓勵自己，是成長的動力。","id":"g305"},{"cat":"情緒調節","kind":"mc","q":"生氣時用「我覺得」說話，下列哪一句比較合適？","a":"我覺得很難過，因為你沒有等我","w":["你都不管我","你是壞人"],"ex":"描述感受，比責怪更有效。","id":"g306"},{"cat":"情緒調節","kind":"mc","q":"朋友因為你的玩笑而生氣，你可以怎麼做？","a":"道歉，並說明你不是故意的","w":["說他開不起玩笑","不理他"],"ex":"尊重別人的感受，就要適時道歉。","id":"g307"},{"cat":"情緒調節","kind":"mc","q":"弟弟妹妹一直吵你，你很不耐煩，可以怎麼做？","a":"先深呼吸，再好好告訴他你需要安靜","w":["大聲罵他","打他一下"],"ex":"冷靜溝通，是比較好的處理方式。","id":"g308"},{"cat":"情緒調節","kind":"mc","q":"感覺很疲倦，卻有一堆作業要做，下列哪種方式比較好？","a":"先休息一下，再分次完成","w":["硬撐到半夜","整個放棄不寫"],"ex":"適度休息，效率才會更好。","id":"g309"},{"cat":"情緒調節","kind":"mc","q":"被同學拒絕邀約，你覺得難過，可以怎麼想？","a":"他可能有他的原因，我可以找別人玩","w":["他討厭我","我再也不要跟人玩"],"ex":"不要把拒絕想成全部，也可以找新朋友。","id":"g310"},{"cat":"情緒調節","kind":"mc","q":"在別人面前出糗覺得丟臉，下列哪種想法比較好？","a":"每個人都會出糗，笑一笑就過去了","w":["我再也不敢出門","大家一定都在笑我"],"ex":"接受自己的不完美，也是勇氣。","id":"g311"},{"cat":"情緒調節","kind":"mc","q":"在排隊時被人插隊，你很生氣，可以怎麼做？","a":"先深呼吸，再有禮貌地請他排到後面","w":["大聲罵他","推他一下"],"ex":"平靜地處理，才不會讓事情變更糟。","id":"g312"},{"cat":"情緒調節","kind":"mc","q":"遇到很緊張的事情，下列哪個方法可以讓自己穩定？","a":"慢慢數呼吸，專注在當下","w":["不停想最糟的情況","大聲尖叫"],"ex":"專注當下，可以降低焦慮。","id":"g313"},{"cat":"情緒調節","kind":"mc","q":"被老師提醒上課說話，你覺得被針對，下列哪一種想法比較好？","a":"老師是提醒大家守規矩","w":["老師故意找我麻煩","我不要再上課"],"ex":"換個想法，讓心情好一點。","id":"g314"},{"cat":"情緒調節","kind":"mc","q":"你想要別人了解你的感受，可以怎麼做？","a":"平靜地說出自己的感覺和需求","w":["用沉默來懲罰他","生氣大吼"],"ex":"清楚表達，別人才有機會理解。","id":"g315"},{"cat":"情緒調節","kind":"mc","q":"晚上睡不著，覺得很緊張，可以怎麼做？","a":"深呼吸，聽輕音樂，放鬆身體","w":["一直滑手機","熬夜寫作業"],"ex":"放鬆的方式，有助於睡眠。","id":"g316"},{"cat":"友誼合作","kind":"tf","q":"真正的朋友，會在我們需要時伸出援手。","a":"是","w":["否"],"ex":"互相幫助，是友誼的基礎。","id":"g317"},{"cat":"友誼合作","kind":"tf","q":"朋友之間有意見不同是正常的，可以溝通解決。","a":"是","w":["否"],"ex":"好好說，友情更穩固。","id":"g318"},{"cat":"友誼合作","kind":"tf","q":"只有跟我很像的人，才能成為我的朋友。","a":"否","w":["是"],"ex":"不同個性的人，也可以成為好朋友。","id":"g319"},{"cat":"友誼合作","kind":"tf","q":"小組合作時，每個人都有責任完成自己的部分。","a":"是","w":["否"],"ex":"責任感，讓團隊成功。","id":"g320"},{"cat":"友誼合作","kind":"tf","q":"朋友做錯事，我應該幫他隱瞞，不要告訴任何人。","a":"否","w":["是"],"ex":"可以勸他改正，必要時請大人協助。","id":"g321"},{"cat":"友誼合作","kind":"tf","q":"有好朋友在身邊，我們就不需要結交新朋友。","a":"否","w":["是"],"ex":"多認識人，也能讓生活更豐富。","id":"g322"},{"cat":"友誼合作","kind":"tf","q":"朋友不小心傷害了我，他道歉時，我可以選擇原諒。","a":"是","w":["否"],"ex":"寬容讓友誼更長久。","id":"g323"},{"cat":"友誼合作","kind":"tf","q":"分組時，把能力不好的同學排除在外，可以讓團隊更好。","a":"否","w":["是"],"ex":"每個人都有自己的長處，合作才能成功。","id":"g324"},{"cat":"友誼合作","kind":"tf","q":"別人說了我的壞話，我也要說他的壞話才公平。","a":"否","w":["是"],"ex":"以牙還牙只會讓關係更糟。","id":"g325"},{"cat":"友誼合作","kind":"tf","q":"好朋友之間，也需要尊重彼此的界線與隱私。","a":"是","w":["否"],"ex":"親近不代表可以不尊重。","id":"g326"},{"cat":"友誼合作","kind":"tf","q":"小組報告時，有人沒做好，我們就一起責怪他。","a":"否","w":["是"],"ex":"找出原因，一起幫忙，才是合作。","id":"g327"},{"cat":"友誼合作","kind":"tf","q":"關心朋友的感受，可以讓友誼更緊密。","a":"是","w":["否"],"ex":"體貼是友誼的黏著劑。","id":"g328"},{"cat":"友誼合作","kind":"tf","q":"為了得到朋友，什麼都答應他，即使自己不願意也沒關係。","a":"否","w":["是"],"ex":"真正的朋友會尊重你的意願。","id":"g329"},{"cat":"友誼合作","kind":"tf","q":"互相分享快樂與難過，是友誼的重要部分。","a":"是","w":["否"],"ex":"分享，讓友誼更深。","id":"g330"},{"cat":"友誼合作","kind":"tf","q":"小組分工時，我只做自己喜歡的部分，其他不關我的事。","a":"否","w":["是"],"ex":"合作需要大家一起承擔。","id":"g331"},{"cat":"友誼合作","kind":"tf","q":"當朋友取得成就時，真心為他高興，是成熟的友誼表現。","a":"是","w":["否"],"ex":"為別人高興，是一種美好的品格。","id":"g332"},{"cat":"友誼合作","kind":"tf","q":"新同學來班上，我們可以主動和他打招呼。","a":"是","w":["否"],"ex":"友善的開始，讓新同學不孤單。","id":"g333"},{"cat":"友誼合作","kind":"tf","q":"朋友邀我一起做不對的事，我可以勇敢說「不」。","a":"是","w":["否"],"ex":"拒絕不好的邀請，是勇敢的表現。","id":"g334"},{"cat":"友誼合作","kind":"tf","q":"友誼就是要時時刻刻黏在一起，不能有自己的時間。","a":"否","w":["是"],"ex":"友誼需要彼此留點空間。","id":"g335"},{"cat":"友誼合作","kind":"tf","q":"在團體活動中，大家輪流擔任不同的角色，可以學到更多。","a":"是","w":["否"],"ex":"輪流嘗試，團隊更有活力。","id":"g336"},{"cat":"友誼合作","kind":"tf","q":"當朋友心情不好，我可以主動陪他聊聊。","a":"是","w":["否"],"ex":"主動關心，讓友情更溫暖。","id":"g337"},{"cat":"友誼合作","kind":"tf","q":"如果朋友和別人玩，我就應該生氣並要他不能跟別人玩。","a":"否","w":["是"],"ex":"友誼不是佔有，大家都可以有不同朋友。","id":"g338"},{"cat":"友誼合作","kind":"mc","q":"小組作業中，有組員不太會做，你可以怎麼做？","a":"耐心教他，一起完成","w":["責怪他拖累大家","把他的部分搶來做完"],"ex":"互相幫助，才是真正的合作。","id":"g339"},{"cat":"友誼合作","kind":"mc","q":"你想邀請同學一起玩，你可以怎麼說？","a":"要不要一起玩？","w":["你快點過來","我不想跟你玩"],"ex":"友善的邀請，讓人更願意加入。","id":"g340"},{"cat":"友誼合作","kind":"mc","q":"朋友告訴你他的秘密，你應該怎麼做？","a":"保守秘密，不隨便告訴別人","w":["告訴其他同學","在班上說出來"],"ex":"信任是友誼的基礎。","id":"g341"},{"cat":"友誼合作","kind":"mc","q":"同學的玩具壞了很傷心，你可以怎麼做？","a":"安慰他，並問需不需要幫忙","w":["說「壞了就算了」","嘲笑他"],"ex":"關心朋友的心情，友誼更溫暖。","id":"g342"},{"cat":"友誼合作","kind":"mc","q":"好朋友答應你的事沒做到，你可以怎麼做？","a":"告訴他你的感受，聽聽他的理由","w":["從此不理他","在背後說他壞話"],"ex":"好好溝通，可以修補關係。","id":"g343"},{"cat":"友誼合作","kind":"mc","q":"分組活動時，沒被邀請的同學站在旁邊，你可以怎麼做？","a":"邀請他加入","w":["假裝沒看到","取笑他"],"ex":"主動邀請，讓大家都有位置。","id":"g344"},{"cat":"友誼合作","kind":"mc","q":"你和朋友玩遊戲意見不同，下列哪種方法比較好？","a":"輪流決定，或一起想辦法","w":["大吵一架","互相不理對方"],"ex":"輪流和討論，可以讓遊戲更好玩。","id":"g345"},{"cat":"友誼合作","kind":"mc","q":"朋友心情不好，你可以怎麼做？","a":"陪他聊聊，讓他知道你在","w":["叫他不要太愛哭","自己去玩"],"ex":"主動陪伴，是朋友最好的支持。","id":"g346"},{"cat":"友誼合作","kind":"mc","q":"當你的朋友取得好成績，你可以怎麼回應？","a":"真心恭喜他","w":["嫉妒他","說他一定作弊"],"ex":"分享別人的喜悅，是成熟的表現。","id":"g347"},{"cat":"友誼合作","kind":"mc","q":"同學之間因為小事吵架，你可以怎麼做？","a":"幫忙化解，提醒他們好好溝通","w":["在旁邊煽風點火","假裝沒看到"],"ex":"當和事佬，讓班級更和諧。","id":"g348"},{"cat":"友誼合作","kind":"mc","q":"團體合作時，遇到意見不同，下列哪個做法最好？","a":"大家輪流發表意見，找出共同方案","w":["只聽最大聲的人","只做自己喜歡的方式"],"ex":"傾聽不同的聲音，是合作的重點。","id":"g349"},{"cat":"友誼合作","kind":"mc","q":"好朋友搬家要轉學，你覺得難過，可以怎麼做？","a":"約定保持聯絡，並祝福他","w":["生氣說他背叛你","不理他"],"ex":"友情不會因距離消失。","id":"g350"},{"cat":"友誼合作","kind":"mc","q":"看到朋友被別人欺負，你可以怎麼做？","a":"勇敢站出來，或找老師幫忙","w":["假裝沒看到","跟著一起欺負"],"ex":"幫助朋友，是真正的義氣。","id":"g351"},{"cat":"友誼合作","kind":"mc","q":"與人合作時，下列哪一種態度比較好？","a":"願意傾聽、也願意分享","w":["只要自己的方法","一直批評別人"],"ex":"開放的態度，可以讓合作更順利。","id":"g352"},{"cat":"友誼合作","kind":"mc","q":"朋友想借你的筆記，但你自己也要用，可以怎麼說？","a":"等我用完，我借你好嗎？","w":["不借，自己寫","丟給他就好"],"ex":"坦誠表達，也顧及別人需求。","id":"g353"},{"cat":"友誼合作","kind":"mc","q":"在遊戲中，我們輸了，你可以怎麼做？","a":"鼓勵隊友，一起檢討","w":["責怪隊友","生氣退出"],"ex":"輸贏之外，更重要的是團隊精神。","id":"g354"},{"cat":"友誼合作","kind":"mc","q":"你和朋友鬧彆扭，想要和好，可以怎麼做？","a":"主動邀請他聊聊，說出自己的想法","w":["等他先道歉","永遠不理他"],"ex":"主動示好，需要勇氣。","id":"g355"},{"cat":"友誼合作","kind":"mc","q":"有人提出一個你不太同意的想法，你可以怎麼說？","a":"我有另一個想法，我們可以一起討論嗎？","w":["你的想法很爛","我不聽你的"],"ex":"有禮貌地表達，大家才願意討論。","id":"g356"},{"cat":"友誼合作","kind":"mc","q":"你發現朋友交到新朋友，下列哪個想法比較好？","a":"朋友變多了，真替他高興","w":["他不再喜歡我了","我要他不要和別人玩"],"ex":"友誼不是佔有，大家都可以擁有更多朋友。","id":"g357"},{"cat":"友誼合作","kind":"mc","q":"遇到團隊中有人做事特別慢，你可以怎麼做？","a":"問他需要什麼幫助","w":["一直催他","罵他很笨"],"ex":"耐心協助，才能讓團隊更好。","id":"g358"},{"cat":"友誼合作","kind":"mc","q":"你想和朋友一起完成一件大事，下列哪一種做法最好？","a":"分工合作，各自負責一部分","w":["每個人都想自己做","等別人來幫忙"],"ex":"分工，能讓事情更有效率。","id":"g359"},{"cat":"友誼合作","kind":"mc","q":"朋友被誤會了，你知道真相，你可以怎麼做？","a":"為他說明事實","w":["保持沉默","跟著大家取笑他"],"ex":"替朋友發聲，是勇氣的表現。","id":"g360"},{"cat":"友誼合作","kind":"mc","q":"看到同學一個人在校園角落，你可以怎麼做？","a":"走過去問他要不要一起玩","w":["假裝沒看到","嘲笑他沒朋友"],"ex":"一個小小的邀請，可以改變他的一天。","id":"g361"},{"cat":"友誼合作","kind":"mc","q":"朋友有進步，你想鼓勵他，可以怎麼說？","a":"你進步了，真棒！","w":["這有什麼了不起","你運氣好而已"],"ex":"真心的鼓勵，讓朋友更有信心。","id":"g362"},{"cat":"友誼合作","kind":"mc","q":"你和朋友對遊戲規則有爭議，可以怎麼做？","a":"請老師或旁邊的同學評評理，或重新商量","w":["搶東西","大聲吵鬧"],"ex":"尋求公正的第三方，是和平的做法。","id":"g363"},{"cat":"友誼合作","kind":"mc","q":"班級活動要選擇節目，大家意見不同，你可以怎麼做？","a":"用投票或討論，找出大家都能接受的方案","w":["只做自己喜歡的","不參加"],"ex":"尊重多數，並照顧少數想法。","id":"g364"},{"cat":"友誼合作","kind":"mc","q":"你覺得朋友做得不對，想提醒他，下列哪一種方式比較好？","a":"私下、溫和地說","w":["在大家面前指責","在背後批評"],"ex":"給對方留面子，比較容易接受。","id":"g365"},{"cat":"友誼合作","kind":"mc","q":"有同學成績不好，被朋友嘲笑，你可以怎麼做？","a":"告訴大家每個人都有擅長的事","w":["跟著笑他","假裝沒聽到"],"ex":"尊重差異，勇敢說出善意的話。","id":"g366"},{"cat":"友誼合作","kind":"mc","q":"在團隊中，每個人的優點都不同，這代表什麼？","a":"大家可以互補，一起完成目標","w":["有人比較差","應該只讓厲害的人做"],"ex":"多元的優點，能讓團隊更完整。","id":"g367"},{"cat":"友誼合作","kind":"mc","q":"好朋友跟你說「我不想再做這件事了」，你可以怎麼回應？","a":"問他原因，一起想辦法","w":["逼他繼續做","責怪他不夠努力"],"ex":"傾聽理由，才能真正幫上忙。","id":"g368"},{"cat":"尊重反霸凌","kind":"tf","q":"每個人的長相、個性和家庭都不一樣，我們要彼此尊重。","a":"是","w":["否"],"ex":"尊重差異，是友善的第一步。","id":"g369"},{"cat":"尊重反霸凌","kind":"tf","q":"幫同學取難聽的綽號，只要他笑就是沒關係。","a":"否","w":["是"],"ex":"對方可能只是在忍耐，不喜歡的綽號就不要叫。","id":"g370"},{"cat":"尊重反霸凌","kind":"tf","q":"看到同學被欺負，我雖然沒有參與，但也可以幫忙求助。","a":"是","w":["否"],"ex":"旁觀者也能成為幫助的力量。","id":"g371"},{"cat":"尊重反霸凌","kind":"tf","q":"霸凌就是只有打人才算。","a":"否","w":["是"],"ex":"言語、孤立、傳謠言、網路攻擊，也都是霸凌。","id":"g372"},{"cat":"尊重反霸凌","kind":"tf","q":"開玩笑時，要注意對方有沒有感到不舒服。","a":"是","w":["否"],"ex":"好笑不能建立在別人的難過上。","id":"g373"},{"cat":"尊重反霸凌","kind":"tf","q":"只要大家都這樣做，就不算霸凌。","a":"否","w":["是"],"ex":"人多也不代表是對的，傷害別人就是不對。","id":"g374"},{"cat":"尊重反霸凌","kind":"tf","q":"被欺負的人如果告訴老師，是勇敢的表現。","a":"是","w":["否"],"ex":"求助不是告狀，是保護自己與別人。","id":"g375"},{"cat":"尊重反霸凌","kind":"tf","q":"看到同學被排擠，我可以邀請他一起玩。","a":"是","w":["否"],"ex":"一個善意的邀請，可能改變他的一整天。","id":"g376"},{"cat":"尊重反霸凌","kind":"tf","q":"嘲笑別人的外表，只是玩笑，不會傷人。","a":"否","w":["是"],"ex":"外表的嘲笑，可能讓人受傷很久。","id":"g377"},{"cat":"尊重反霸凌","kind":"tf","q":"每個人都有被尊重的權利。","a":"是","w":["否"],"ex":"尊重，是人與人相處的基礎。","id":"g378"},{"cat":"尊重反霸凌","kind":"tf","q":"如果我不喜歡某個同學，就可以叫大家都不要跟他玩。","a":"否","w":["是"],"ex":"不喜歡也要尊重，不能排擠別人。","id":"g379"},{"cat":"尊重反霸凌","kind":"tf","q":"不同的文化、語言和生活習慣，都值得被尊重。","a":"是","w":["否"],"ex":"多元，讓社會更豐富。","id":"g380"},{"cat":"尊重反霸凌","kind":"tf","q":"霸凌被發現了，只要說對不起就沒事了。","a":"否","w":["是"],"ex":"道歉很重要，也要真正改變行為。","id":"g381"},{"cat":"尊重反霸凌","kind":"tf","q":"看到有人被欺負，我可以先陪在受害者身邊，讓他知道不孤單。","a":"是","w":["否"],"ex":"陪伴與支持，是給對方的溫暖。","id":"g382"},{"cat":"尊重反霸凌","kind":"tf","q":"取笑同學的口音，是很有趣的玩笑。","a":"否","w":["是"],"ex":"口音是個人特色，不應被嘲笑。","id":"g383"},{"cat":"尊重反霸凌","kind":"tf","q":"說別人的壞話，不會對他造成影響。","a":"否","w":["是"],"ex":"閒話可能讓人受傷，甚至被孤立。","id":"g384"},{"cat":"尊重反霸凌","kind":"tf","q":"如果我被欺負，我應該告訴爸爸媽媽或老師。","a":"是","w":["否"],"ex":"信任的大人可以幫助我們解決問題。","id":"g385"},{"cat":"尊重反霸凌","kind":"tf","q":"男生可以有溫柔的特質，女生也可以有勇敢的特質。","a":"是","w":["否"],"ex":"每個人都可以做真實的自己。","id":"g386"},{"cat":"尊重反霸凌","kind":"tf","q":"不同性格的同學，也可以成為好朋友。","a":"是","w":["否"],"ex":"差異讓友誼更有趣。","id":"g387"},{"cat":"尊重反霸凌","kind":"tf","q":"別人犯錯，我就可以公開羞辱他。","a":"否","w":["是"],"ex":"公開羞辱會傷害人，應該私下提醒。","id":"g388"},{"cat":"尊重反霸凌","kind":"mc","q":"看到同學被其他人嘲笑，你可以怎麼做？","a":"勇敢說「不要這樣」，並找老師幫忙","w":["跟著一起笑","假裝沒看到"],"ex":"說出口，也可以保護受傷的人。","id":"g389"},{"cat":"尊重反霸凌","kind":"mc","q":"同學的長相和大家不太一樣，你可以怎麼做？","a":"友善對待，尊重他","w":["取笑他","不理他"],"ex":"每個人都值得被尊重。","id":"g390"},{"cat":"尊重反霸凌","kind":"mc","q":"下列哪一種行為屬於霸凌？","a":"多人一起長期排擠或嘲笑同學","w":["同學之間正常的遊戲","友善的互相幫助"],"ex":"重複的傷害行為，才是霸凌。","id":"g391"},{"cat":"尊重反霸凌","kind":"mc","q":"有人在班上散播同學的謠言，你可以怎麼做？","a":"不轉傳，並告訴老師","w":["跟著大家傳","在網路上發布"],"ex":"不傳播謠言，也能保護別人。","id":"g392"},{"cat":"尊重反霸凌","kind":"mc","q":"同學被叫了一個不好聽的綽號，他說不喜歡，你應該怎麼做？","a":"不要叫，改叫他的名字","w":["繼續叫，因為很好玩","在大家面前叫更大聲"],"ex":"尊重別人的感受，不要用綽號傷人。","id":"g393"},{"cat":"尊重反霸凌","kind":"mc","q":"看到班上有同學總是被分組剩下，你可以怎麼做？","a":"主動邀請他加入你的組","w":["假裝沒看到","笑他沒人要"],"ex":"友善行動，可以讓人不再孤單。","id":"g394"},{"cat":"尊重反霸凌","kind":"mc","q":"你被同學欺負，感覺很難過，可以怎麼做？","a":"告訴老師或信任的大人","w":["一個人忍耐","報復對方"],"ex":"求助，才能解決問題。","id":"g395"},{"cat":"尊重反霸凌","kind":"mc","q":"有同學因為膚色或口音被嘲笑，你可以怎麼做？","a":"告訴他們這樣不尊重，並陪伴被嘲笑的人","w":["跟著笑","假裝沒聽到"],"ex":"友善與勇氣，可以減少歧視。","id":"g396"},{"cat":"尊重反霸凌","kind":"mc","q":"看到有人使用暴力，你可以怎麼做？","a":"立刻告訴大人，不要自己介入危險","w":["拍影片取樂","加入打人"],"ex":"安全第一，找大人處理。","id":"g397"},{"cat":"尊重反霸凌","kind":"mc","q":"同學因為家庭狀況不同被議論，你可以怎麼做？","a":"不隨便議論，尊重每個人的家庭","w":["跟著大家說閒話","嘲笑他"],"ex":"尊重差異，是友善的表現。","id":"g398"},{"cat":"尊重反霸凌","kind":"mc","q":"關於身體的玩笑，下列哪個做法比較好？","a":"不開別人身體的玩笑","w":["為了好玩亂說","嘲笑別人身材"],"ex":"尊重身體，不用別人的外表開玩笑。","id":"g399"},{"cat":"尊重反霸凌","kind":"mc","q":"同學因為反應慢被大家取笑，你可以怎麼做？","a":"耐心幫他，並請大家別取笑","w":["跟著大家笑","在旁邊看熱鬧"],"ex":"尊重別人的步調，是友善的體現。","id":"g400"},{"cat":"尊重反霸凌","kind":"mc","q":"你不喜歡某位同學，可以怎麼做？","a":"保持禮貌，不傷害他","w":["在背後說他壞話","聯合大家排擠他"],"ex":"不喜歡，也不能傷害別人。","id":"g401"},{"cat":"尊重反霸凌","kind":"mc","q":"你說了讓別人難過的話，之後你知道自己錯了，可以怎麼做？","a":"向對方道歉，並改變說話方式","w":["當作沒說過","說他太敏感"],"ex":"承認錯誤，並嘗試改變。","id":"g402"},{"cat":"尊重反霸凌","kind":"mc","q":"發現有同學在網路上被人罵，你可以怎麼做？","a":"不加入，並協助他向大人求助","w":["也留言罵他","截圖嘲笑他"],"ex":"不跟著做，並給予支持。","id":"g403"},{"cat":"尊重反霸凌","kind":"mc","q":"在團體中，有人總是被取笑，這時候你可以怎麼做？","a":"表達你不認同取笑，並關心被取笑的人","w":["跟著取笑","不管他"],"ex":"站出來，是勇氣也是善意。","id":"g404"},{"cat":"尊重反霸凌","kind":"mc","q":"看到有人穿的衣服比較舊，你可以怎麼做？","a":"不評論，友善相處","w":["嘲笑他","不跟他玩"],"ex":"每個人的條件不同，尊重最重要。","id":"g405"},{"cat":"尊重反霸凌","kind":"mc","q":"有人說「你不能跟他玩，不然我就不跟你玩」，你可以怎麼做？","a":"說「我可以和大家都玩」","w":["照做，一起排擠他","威脅回去"],"ex":"不被脅迫，守住善意。","id":"g406"},{"cat":"尊重反霸凌","kind":"mc","q":"當你被一群人圍住嘲笑，你可以怎麼做？","a":"盡快離開，找老師或信任的大人","w":["打回去","忍耐不說"],"ex":"保護自己，並尋求協助。","id":"g407"},{"cat":"尊重反霸凌","kind":"mc","q":"發現朋友有欺負別人的行為，你可以怎麼做？","a":"勸他停止，並告訴大人","w":["跟他一起欺負","不管他"],"ex":"勇敢提醒，是真正的朋友。","id":"g408"},{"cat":"尊重反霸凌","kind":"mc","q":"同學的名字比較特別，你可以怎麼做？","a":"認真記住並尊重地稱呼","w":["拿來開玩笑","亂叫"],"ex":"尊重別人的名字，也是尊重他本人。","id":"g409"},{"cat":"尊重反霸凌","kind":"mc","q":"你發現新來的同學不會說我們的語言，你可以怎麼做？","a":"耐心教他，並友善相處","w":["嘲笑他","不理他"],"ex":"友善與耐心，讓新同學快樂。","id":"g410"},{"cat":"尊重反霸凌","kind":"mc","q":"你被排擠時，覺得很孤單，下列哪個做法比較好？","a":"找信任的人說說，也尋求老師協助","w":["獨自承受","責怪自己"],"ex":"不要一個人扛，有人可以幫你。","id":"g411"},{"cat":"尊重反霸凌","kind":"mc","q":"關於「歧視」，下列哪一句話是正確的？","a":"因為對方的特質而不公平對待，是歧視","w":["歧視是一種玩笑","歧視不會傷人"],"ex":"歧視會傷害別人，也破壞社會的和諧。","id":"g412"},{"cat":"尊重反霸凌","kind":"mc","q":"有同學因為考試成績不好被取笑，你可以怎麼做？","a":"告訴他每個人都有擅長的事，並鼓勵他","w":["取笑他","不理他"],"ex":"鼓勵與接納，能讓人更有信心。","id":"g413"},{"cat":"求助保護","kind":"tf","q":"當我感到不舒服或害怕時，可以告訴信任的大人。","a":"是","w":["否"],"ex":"說出來，才能得到幫助。","id":"g414"},{"cat":"求助保護","kind":"tf","q":"我的身體是我自己的，別人不能在我不願意時碰我。","a":"是","w":["否"],"ex":"身體自主權很重要。","id":"g415"},{"cat":"求助保護","kind":"tf","q":"陌生人給我糖果，只要他看起來很和善，就可以跟著他走。","a":"否","w":["是"],"ex":"不隨便接受陌生人的東西，也不跟他走。","id":"g416"},{"cat":"求助保護","kind":"tf","q":"遇到緊急危險，可以撥打 119 求救火災或救護。","a":"是","w":["否"],"ex":"119 是消防與救護電話。","id":"g417"},{"cat":"求助保護","kind":"tf","q":"看到有人遇到危險，可以撥打 110 報警。","a":"是","w":["否"],"ex":"110 是報警專線。","id":"g418"},{"cat":"求助保護","kind":"tf","q":"「保護專線」113 可以協助遇到家庭暴力或兒少受傷害的人。","a":"是","w":["否"],"ex":"113 是全國保護專線，24 小時都有人協助。","id":"g419"},{"cat":"求助保護","kind":"tf","q":"被威脅「不能告訴別人」時，我應該照做，不要說出去。","a":"否","w":["是"],"ex":"遇到威脅要告訴信任的大人。","id":"g420"},{"cat":"求助保護","kind":"tf","q":"如果覺得不舒服的碰觸，我可以大聲說「不要」。","a":"是","w":["否"],"ex":"你有權利拒絕不舒服的對待。","id":"g421"},{"cat":"求助保護","kind":"tf","q":"網路上認識的人要我給他住址和學校名稱，我可以給。","a":"否","w":["是"],"ex":"個人資料不能隨便給陌生人。","id":"g422"},{"cat":"求助保護","kind":"tf","q":"如果朋友說他想傷害自己，我應該告訴大人，幫助他得到協助。","a":"是","w":["否"],"ex":"生命很重要，要找可信任的大人。","id":"g423"},{"cat":"求助保護","kind":"tf","q":"遇到壞人，我一定要自己想辦法打倒他。","a":"否","w":["是"],"ex":"保護自己最重要，快找大人或求助。","id":"g424"},{"cat":"求助保護","kind":"tf","q":"在擁擠的地方，記得跟緊家人，避免走散。","a":"是","w":["否"],"ex":"走散時，要找穿制服的工作人員。","id":"g425"},{"cat":"求助保護","kind":"tf","q":"生活中遇到困難，不好意思說，所以自己默默承受最好。","a":"否","w":["是"],"ex":"適時求助，可以讓問題更快解決。","id":"g426"},{"cat":"求助保護","kind":"tf","q":"如果我在外迷路，可以向穿制服的警察或店員求助。","a":"是","w":["否"],"ex":"找可信任的人幫忙。","id":"g427"},{"cat":"求助保護","kind":"mc","q":"有陌生人說要帶你去看小狗，你應該怎麼做？","a":"拒絕並走開，告訴大人","w":["跟他走","問他小狗在哪裡"],"ex":"不跟陌生人走，保護自己。","id":"g428"},{"cat":"求助保護","kind":"mc","q":"感覺有人讓你不舒服，你應該怎麼做？","a":"告訴信任的大人，並遠離讓你不舒服的人","w":["不說出去","忍耐"],"ex":"說出來，才能被保護。","id":"g429"},{"cat":"求助保護","kind":"mc","q":"在學校遇到危險狀況時，首先可以怎麼做？","a":"立刻找老師或大人幫忙","w":["自己面對","不告訴任何人"],"ex":"找大人，是最安全的方法。","id":"g430"},{"cat":"求助保護","kind":"mc","q":"在家裡發現瓦斯味，你應該怎麼做？","a":"打開窗戶、不開電器，並通知大人","w":["點火查看","開電燈看看"],"ex":"瓦斯很危險，要避免火花。","id":"g431"},{"cat":"求助保護","kind":"mc","q":"你一個人在家，有陌生人敲門，你應該怎麼做？","a":"不開門，並通知家人","w":["馬上開門","告訴他家人不在"],"ex":"保護自己，不隨便開門。","id":"g432"},{"cat":"求助保護","kind":"mc","q":"發現朋友被人欺負，但自己不敢出面，可以怎麼做？","a":"告訴老師或其他大人","w":["假裝沒看到","跟著嘲笑"],"ex":"找大人，也能幫助朋友。","id":"g433"},{"cat":"求助保護","kind":"mc","q":"遇到火災，下列哪個做法正確？","a":"用濕毛巾搗口鼻，低姿勢離開","w":["搭電梯逃生","躲在房間不出來"],"ex":"低姿勢可以減少吸入濃煙。","id":"g434"},{"cat":"求助保護","kind":"mc","q":"在網路上收到陌生人要求見面，你應該怎麼做？","a":"不理會，並告訴大人","w":["答應他","給他地址"],"ex":"網路上的人不一定是真的，要小心。","id":"g435"},{"cat":"求助保護","kind":"mc","q":"看到有人跌倒受傷，你可以怎麼做？","a":"通知大人或老師協助","w":["假裝沒看到","拍照上傳網路"],"ex":"立刻求助，讓他得到幫忙。","id":"g436"},{"cat":"求助保護","kind":"mc","q":"如果發現有人在你不願意的情況下拍你的照片，你可以怎麼做？","a":"告訴他停止，並告訴大人","w":["讓他拍","自己忍耐"],"ex":"你有權利保護自己的隱私。","id":"g437"},{"cat":"求助保護","kind":"mc","q":"同學告訴你他在家裡被打，你可以怎麼做？","a":"告訴老師或輔導室，請專業人員協助","w":["保守秘密，不說出去","取笑他"],"ex":"關心他，並引導他向大人求助。","id":"g438"},{"cat":"求助保護","kind":"mc","q":"下列哪個電話可以在遇到緊急狀況時求助？","a":"110 或 119","w":["114","104"],"ex":"緊急狀況要打 110（警察）或 119（消防、救護）。","id":"g439"},{"cat":"求助保護","kind":"mc","q":"發現同學心情很低落，常說不想活了，你可以怎麼做？","a":"告訴老師或家人，請專業人員協助","w":["當作玩笑","不理他"],"ex":"生命很重要，要找大人幫忙；也可以撥 1925 安心專線。","id":"g440"},{"cat":"求助保護","kind":"mc","q":"在百貨公司和家人走散，應該怎麼做？","a":"待在原地或找穿制服的店員求助","w":["自己到處亂跑","跟陌生人走"],"ex":"在安全的地方等待，家人才容易找到你。","id":"g441"},{"cat":"求助保護","kind":"mc","q":"在路上遇到可疑的人一直跟著你，你應該怎麼做？","a":"走到有人的地方，或向商店、警察求助","w":["獨自走小路","加快速度跑進暗巷"],"ex":"找人多的地方，求助最安全。","id":"g442"},{"cat":"求助保護","kind":"mc","q":"收到陌生網友的禮物或連結，你可以怎麼做？","a":"不點、不收，並告訴大人","w":["馬上打開看看","把個人資料填進去"],"ex":"陌生連結可能有危險，不要隨便點。","id":"g443"},{"cat":"求助保護","kind":"mc","q":"你不小心受傷流血了，可以怎麼做？","a":"告訴老師或大人，並到保健室處理","w":["自己忍著","用髒手擦拭"],"ex":"讓專業的人幫你處理傷口。","id":"g444"},{"cat":"場所禮儀","kind":"tf","q":"在圖書館裡可以大聲聊天、嬉鬧。","a":"否","w":["是"],"ex":"圖書館需要安靜，才不會打擾別人。","id":"g445"},{"cat":"場所禮儀","kind":"tf","q":"搭乘公車、捷運時，要把座位讓給有需要的人。","a":"是","w":["否"],"ex":"讓座是體貼的表現。","id":"g446"},{"cat":"場所禮儀","kind":"tf","q":"排隊時可以插隊，只要動作快就不會被發現。","a":"否","w":["是"],"ex":"插隊對後面的人不公平。","id":"g447"},{"cat":"場所禮儀","kind":"tf","q":"在公園玩耍後，把垃圾帶走或丟進垃圾桶，是愛護環境的表現。","a":"是","w":["否"],"ex":"公共空間大家都要維護。","id":"g448"},{"cat":"場所禮儀","kind":"tf","q":"在電影院裡，用手機大聲講電話沒關係。","a":"否","w":["是"],"ex":"會打擾別人觀影。","id":"g449"},{"cat":"場所禮儀","kind":"tf","q":"走樓梯時靠右走，不推擠，可以避免意外。","a":"是","w":["否"],"ex":"守秩序，保護大家的安全。","id":"g450"},{"cat":"場所禮儀","kind":"tf","q":"在餐廳，可以在座位間奔跑追逐。","a":"否","w":["是"],"ex":"可能撞到服務生或其他客人，很危險。","id":"g451"},{"cat":"場所禮儀","kind":"tf","q":"公共廁所用完要沖水、洗手，保持整潔。","a":"是","w":["否"],"ex":"愛護公共設施，也是對下一位使用者的尊重。","id":"g452"},{"cat":"場所禮儀","kind":"tf","q":"在學校走廊奔跑，只要沒有人在就沒問題。","a":"否","w":["是"],"ex":"走廊轉角看不到對面，容易發生碰撞。","id":"g453"},{"cat":"場所禮儀","kind":"tf","q":"在公共場所講話要注意音量，不要影響別人。","a":"是","w":["否"],"ex":"音量適中，是基本禮貌。","id":"g454"},{"cat":"場所禮儀","kind":"tf","q":"在博物館裡可以隨意觸摸展品，因為很好玩。","a":"否","w":["是"],"ex":"展品很珍貴，要保持距離，不隨意觸摸。","id":"g455"},{"cat":"場所禮儀","kind":"tf","q":"進入寺廟、教堂或他人信仰場所，要保持安靜與尊重。","a":"是","w":["否"],"ex":"尊重別人的信仰與習慣。","id":"g456"},{"cat":"場所禮儀","kind":"tf","q":"在公車上把腳放在座位上，不會影響別人。","a":"否","w":["是"],"ex":"座位是大家共用的，要保持乾淨。","id":"g457"},{"cat":"場所禮儀","kind":"tf","q":"使用完公共的運動器材，要歸位並保持整潔。","a":"是","w":["否"],"ex":"愛惜公物，也方便下一位使用。","id":"g458"},{"cat":"場所禮儀","kind":"mc","q":"搭電梯時，下列哪種做法最有禮貌？","a":"先讓裡面的人出來，再進去","w":["直接往裡擠","大聲聊天"],"ex":"先出後進，電梯更順暢。","id":"g459"},{"cat":"場所禮儀","kind":"mc","q":"在電影院看電影時，下列哪一種行為不合適？","a":"大聲交談和踢前面座位","w":["關閉手機鈴聲","安靜欣賞"],"ex":"不打擾別人，才能享受電影。","id":"g460"},{"cat":"場所禮儀","kind":"mc","q":"排隊買東西時，如果你看到有人插隊，可以怎麼做？","a":"有禮貌地請他排到後面","w":["大聲罵他","也跟著插隊"],"ex":"禮貌提醒，也維持秩序。","id":"g461"},{"cat":"場所禮儀","kind":"mc","q":"在學校餐廳用餐後，下列哪一種做法是對的？","a":"清理桌面、把餐盤放好","w":["把垃圾留在桌上","把剩菜倒在地上"],"ex":"保持環境整潔，是對工作人員的尊重。","id":"g462"},{"cat":"場所禮儀","kind":"mc","q":"在公園看到地上有垃圾，你可以怎麼做？","a":"撿起來丟進垃圾桶","w":["假裝沒看到","再丟一些在旁邊"],"ex":"愛護環境，從小事做起。","id":"g463"},{"cat":"場所禮儀","kind":"mc","q":"在博物館參觀時，應該怎麼做？","a":"輕聲交談，不亂碰展品","w":["大聲喧嘩","摸展品拍照"],"ex":"尊重展覽，也保護珍貴文物。","id":"g464"},{"cat":"場所禮儀","kind":"mc","q":"乘坐手扶梯時，下列哪種做法比較安全？","a":"握好扶手，站穩","w":["在上面奔跑","坐在階梯上"],"ex":"安全第一，不要做危險的事。","id":"g465"},{"cat":"場所禮儀","kind":"mc","q":"在醫院候診時，下列哪個做法比較合適？","a":"小聲交談、保持安靜","w":["大聲喧嘩","在走廊奔跑"],"ex":"讓病人好好休息。","id":"g466"},{"cat":"場所禮儀","kind":"mc","q":"在升旗典禮時，下列哪一個行為合適？","a":"站好、安靜、莊重","w":["說話、嬉鬧","一直走動"],"ex":"典禮需要莊重與尊重。","id":"g467"},{"cat":"場所禮儀","kind":"mc","q":"在學校使用公共廁所，下列哪一種做法比較好？","a":"保持乾淨、使用完沖水","w":["亂丟衛生紙","在牆上亂畫"],"ex":"愛護廁所，是對全校的尊重。","id":"g468"},{"cat":"場所禮儀","kind":"mc","q":"在公車或捷運上，手機要怎麼使用比較好？","a":"調成靜音，用耳機","w":["外放影片","大聲通話"],"ex":"公共空間，要照顧別人的感受。","id":"g469"},{"cat":"場所禮儀","kind":"mc","q":"在別人家作客，下列哪一個做法是合適的？","a":"保持環境整潔、輕聲說話","w":["到處翻東西","大聲喧嘩"],"ex":"客人也要尊重主人。","id":"g470"},{"cat":"場所禮儀","kind":"mc","q":"在學校操場運動時，下列哪個做法比較好？","a":"注意別人、不推擠","w":["故意推人","丟東西到別人身上"],"ex":"安全運動，大家才開心。","id":"g471"},{"cat":"場所禮儀","kind":"mc","q":"在電梯裡，遇到有人拿著很多東西，你可以怎麼做？","a":"幫忙按樓層或讓位","w":["直接擠進去","一直催他快點"],"ex":"舉手之勞，讓別人更方便。","id":"g472"},{"cat":"場所禮儀","kind":"mc","q":"在圖書館借書後，下列哪個做法比較好？","a":"愛惜書本、準時歸還","w":["把書折角","不還書"],"ex":"愛惜公共財物，是公民的責任。","id":"g473"},{"cat":"場所禮儀","kind":"mc","q":"學校舉辦運動會時，其他班級在比賽，你可以怎麼做？","a":"鼓掌加油，尊重每個選手","w":["大聲噓他們","扔東西"],"ex":"為別人加油，是運動家精神。","id":"g474"},{"cat":"場所禮儀","kind":"mc","q":"在餐廳裡吃飯，下列哪一種做法比較有禮貌？","a":"小聲交談、保持桌面乾淨","w":["大聲說話、亂丟食物","在餐廳裡奔跑"],"ex":"守規矩，讓用餐更愉快。","id":"g475"},{"cat":"網路禮儀","kind":"tf","q":"在網路上說話，也要像面對面一樣有禮貌。","a":"是","w":["否"],"ex":"螢幕後面也是真實的人。","id":"g476"},{"cat":"網路禮儀","kind":"tf","q":"可以把同學的照片未經同意就放到網路上。","a":"否","w":["是"],"ex":"要先得到對方同意，尊重隱私。","id":"g477"},{"cat":"網路禮儀","kind":"tf","q":"在網路上遇到不認識的人要見面，我可以直接答應。","a":"否","w":["是"],"ex":"網路上的人不一定是真的，要告訴大人。","id":"g478"},{"cat":"網路禮儀","kind":"tf","q":"不要在網路上說別人的壞話，也不隨便轉傳不實訊息。","a":"是","w":["否"],"ex":"網路留言也會傷害人。","id":"g479"},{"cat":"網路禮儀","kind":"tf","q":"網路上的密碼，只要告訴好朋友也沒關係。","a":"否","w":["是"],"ex":"密碼是隱私，連好朋友也不能給。","id":"g480"},{"cat":"網路禮儀","kind":"tf","q":"看到網路上有人被罵，我可以加入一起罵。","a":"否","w":["是"],"ex":"不跟著起鬨，也可以幫忙回報或求助。","id":"g481"},{"cat":"網路禮儀","kind":"tf","q":"在群組裡，不亂發惡作劇的訊息，是對別人的尊重。","a":"是","w":["否"],"ex":"網路群組要有秩序。","id":"g482"},{"cat":"網路禮儀","kind":"tf","q":"網路上的資料，只要有人說是真的，就一定是真的。","a":"否","w":["是"],"ex":"要查證資料來源，不隨便相信或轉傳。","id":"g483"},{"cat":"網路禮儀","kind":"tf","q":"玩遊戲時罵隊友，不會影響別人。","a":"否","w":["是"],"ex":"用好的態度合作，遊戲也可以很愉快。","id":"g484"},{"cat":"網路禮儀","kind":"tf","q":"網路上看到讓我不舒服的訊息，我可以告訴老師或家長。","a":"是","w":["否"],"ex":"遇到不舒服要求助。","id":"g485"},{"cat":"網路禮儀","kind":"tf","q":"在網路上，可以隨意使用別人的作品，不用標示來源。","a":"否","w":["是"],"ex":"尊重創作者，使用時要標示來源。","id":"g486"},{"cat":"網路禮儀","kind":"mc","q":"在網路上收到陌生人的好友邀請，你可以怎麼做？","a":"不接受，並告訴大人","w":["立刻接受","給他個人資料"],"ex":"保護自己，不接受陌生人邀請。","id":"g487"},{"cat":"網路禮儀","kind":"mc","q":"在班級群組裡看到同學被嘲笑，你可以怎麼做？","a":"不參與，並告訴老師","w":["跟著嘲笑","轉發截圖"],"ex":"不參與也不轉傳，才是善意。","id":"g488"},{"cat":"網路禮儀","kind":"mc","q":"看到沒有查證的消息，你可以怎麼做？","a":"先查證再轉傳","w":["直接轉傳給所有人","在網路上大肆討論"],"ex":"避免散布不實消息。","id":"g489"},{"cat":"網路禮儀","kind":"mc","q":"玩線上遊戲時，如果有人用很難聽的話罵你，你可以怎麼做？","a":"不回應，並使用檢舉或封鎖功能","w":["罵回去","把帳號給他"],"ex":"冷靜處理，保護自己。","id":"g490"},{"cat":"網路禮儀","kind":"mc","q":"要使用別人拍的照片時，下列哪一種做法比較合適？","a":"先徵求同意，並標示來源","w":["直接下載使用","說是自己拍的"],"ex":"尊重別人的創作。","id":"g491"},{"cat":"網路禮儀","kind":"mc","q":"在網路上發文之前，下列哪個想法比較好？","a":"這樣說會不會傷害別人？","w":["反正沒人知道是我","大家都這樣說"],"ex":"三思而後發，才不會後悔。","id":"g492"},{"cat":"網路禮儀","kind":"mc","q":"在聊天群組裡，下列哪一種行為比較有禮貌？","a":"不洗版、不亂傳訊息","w":["大量傳貼圖打擾別人","半夜一直發訊息"],"ex":"尊重別人的時間與空間。","id":"g493"},{"cat":"網路禮儀","kind":"mc","q":"收到不知道來源的連結，你可以怎麼做？","a":"不點開，並詢問大人","w":["直接點開","轉給別人"],"ex":"陌生連結可能帶來危險。","id":"g494"},{"cat":"網路禮儀","kind":"mc","q":"同學的帳號被盜用，傳來奇怪的訊息，你可以怎麼做？","a":"提醒同學並告訴大人","w":["照著點連結","轉傳給別人"],"ex":"幫助別人，也保護自己。","id":"g495"},{"cat":"網路禮儀","kind":"mc","q":"看到網路上有人在說謊或散布謠言，你可以怎麼做？","a":"不轉傳，並提醒查證","w":["大力轉發","攻擊他"],"ex":"理性面對，避免擴散。","id":"g496"},{"cat":"網路禮儀","kind":"mc","q":"在網路上看到別人的隱私資料（例如電話、地址），你可以怎麼做？","a":"不轉傳，並提醒對方刪除","w":["轉發給朋友","在網路公開"],"ex":"尊重隱私，是基本的網路禮儀。","id":"g497"},{"cat":"網路禮儀","kind":"mc","q":"玩遊戲時，隊友表現不好，你可以怎麼說？","a":"沒關係，我們一起努力","w":["你好爛","你拖累大家"],"ex":"鼓勵隊友，才能越玩越開心。","id":"g498"},{"cat":"網路禮儀","kind":"mc","q":"收到網路陌生人的私訊，說你中獎了，要你提供資料，你可以怎麼做？","a":"不要回應，並告訴大人","w":["填寫所有資料","轉給朋友"],"ex":"天下沒有白吃的午餐，小心詐騙。","id":"g499"},{"cat":"網路禮儀","kind":"mc","q":"在網路上看到別人做得不對，下列哪個做法比較好？","a":"私訊提醒或向管理員回報","w":["公開羞辱","截圖嘲笑他"],"ex":"善意提醒，比公開攻擊更有效。","id":"g500"}];
